INSERT INTO `attractions` (`id`, `public_id`, `city_id`, `name`, `short_description`, `full_description`, `latitude`, `longitude`, `created_at`, `updated_at`) VALUES
	(1, '1a2751a3-72fe-4ca4-8fef-4b4c151ae240', 25, 'کلیسای سنت استپانوس', 'کلیسای سنت استپانوس (استپانوس مقدس) یکی از مشهورترین، مهم‌ترین و البته زیباترین کلیساهای تاریخی ارامنه در ایران است. این کلیسا در نزدیکی مرز ایران و آذربایجان و در بخش جنوبی رودخانه ارس قرار دارد. فاصله کلیسای سنت استپانوس از شهرستان جلفا در حدود ۲۰ کیلومتر است و برای رسیدن به آن باید به سمت شمال غربی جلفا حرکت کنید و از جاده مرزی بگذرید. سنت استپانوس در منطقه‌ای کوهستانی-دره‌ای قرار گرفته است. به دلیل موقعیت خاص این کلیسا و معماری منحصر به‌فردش یکی از معروف‌ترین جاهای دیدنی آذربایجان شرقی است.\n', 'کلیسای سنت استپانوس (استپانوس مقدس) یکی از مشهورترین، مهم‌ترین و البته زیباترین کلیساهای تاریخی ارامنه در ایران است. این کلیسا در نزدیکی مرز ایران و آذربایجان و در بخش جنوبی رودخانه ارس قرار دارد. فاصله کلیسای سنت استپانوس از شهرستان جلفا در حدود ۲۰ کیلومتر است و برای رسیدن به آن باید به سمت شمال غربی جلفا حرکت کنید و از جاده مرزی بگذرید. سنت استپانوس در منطقه‌ای کوهستانی-دره‌ای قرار گرفته است. به دلیل موقعیت خاص این کلیسا و معماری منحصر به‌فردش یکی از معروف‌ترین جاهای دیدنی آذربایجان شرقی است.\nاین کلیسا چندین سال است که در دست مرمت و از میراث جهانی ثبت شده در یونسکو است. در رابطه با ساخت اولیه کلیسا چندین روایت مختلف وجود دارد و دقیقا مشخص نیست اما طبق آخرین تحقیقات، ساخت کلیسا به دوره صفوی برمی‌گردد. سنت استپانوس یکی از یاران اصلی حضرت عیسی (ع) و اولین شهید در راه ابلاغ دین مسیحیت بوده است که این کلیسا با یاد این قدیس بزرگ، چنین نام گرفته است.\nبخوانید از: بهترین جاهای دیدنی تبریز در تمام فصول + آدرس و معرفی کامل', 38.9791610, 45.4733979, '2026-07-30 20:12:02', '2026-07-30 20:17:04'),
	(2, '7b45ccb3-610b-4aad-9317-878a53d24b38', 25, 'بازار تبریز', 'بازار بزرگ تبریز، یکی از قدیمي‌ترین بازارهای کشور است که هنوز هم بعد از چندین سال، ظاهر سنتی خود را حفظ کرده است. همین ظاهر سنتی و ساخته‌ای که هنوز بعد از چندین سال پابرجاست، این بازار را تبدیل به یکی از مشهورترین جاهای دیدنی آذربایجان شرقی کرده است. بازار تبریز در مرکز شهر تبریز قرار دارد. بازار تبریز بزرگ‌ترین بازار سرپوشیده جهان است و از همین جهت در لیست میراث جهانی یونسکو ثبت شده است. در بازار تبریز دهانه‌ها و گذرهای مختلفی وجود دارد که بسته به نوع فعالیت نام‌گذاری شده‌اند.\nبرای اجاره سوئیت ', 'بازار بزرگ تبریز، یکی از قدیمي‌ترین بازارهای کشور است که هنوز هم بعد از چندین سال، ظاهر سنتی خود را حفظ کرده است. همین ظاهر سنتی و ساخته‌ای که هنوز بعد از چندین سال پابرجاست، این بازار را تبدیل به یکی از مشهورترین جاهای دیدنی آذربایجان شرقی کرده است. بازار تبریز در مرکز شهر تبریز قرار دارد. بازار تبریز بزرگ‌ترین بازار سرپوشیده جهان است و از همین جهت در لیست میراث جهانی یونسکو ثبت شده است. در بازار تبریز دهانه‌ها و گذرهای مختلفی وجود دارد که بسته به نوع فعالیت نام‌گذاری شده‌اند.\nبرای اجاره سوئیت در تبریز کلیک کنید.\nبرای رسیدن به بازار بزرگ تبریز کافیست خود را به شهر تبریز برسانید و آن وقت از هرکس آدرس این بازار را بپرسید مسیر را به شما نشان می‌دهد. پیشنهاد ما این است که برای گشتن این بازار به اندازه کافی زمان بگذارید چراکه به قدری شما را شگفت‌زده می‌کند که نمی‌توانید از آن دل بکنید.', 38.0777150, 46.2976134, '2026-07-30 20:12:02', '2026-07-30 20:17:06'),
	(3, 'e99cc7f7-8947-43ac-bb0e-8ec3650c6c46', 25, 'ائل گلی', 'ائل گلی یکی از معروف‌ترین جاهای دیدنی تبریز است که در بخش جنوب شرقی این شهر قرار دارد. عمارت ائل گلی در میان یک دریاچه مصنوعی قرار دارد که با درختان و پارک احاطه شده است. ائل گلی که قبل از انقلاب شاه گلی نام داشت، در زبان ترکی به معنای دریاچه مردم (دریاچه شاه قبل از انقلاب) است.\nبرای رسیدن به این مجموعه می‌توانید از مترو استفاده کنید و در ایستگاه مترو ائل گلی پیاده شوید یا خود را به بلوار ائل گلی برسانید.\nبخوانید از: گذری به خانه های قدیمی تبریز : 17 عمارت باشکوه تاریخی', 'ائل گلی یکی از معروف‌ترین جاهای دیدنی تبریز است که در بخش جنوب شرقی این شهر قرار دارد. عمارت ائل گلی در میان یک دریاچه مصنوعی قرار دارد که با درختان و پارک احاطه شده است. ائل گلی که قبل از انقلاب شاه گلی نام داشت، در زبان ترکی به معنای دریاچه مردم (دریاچه شاه قبل از انقلاب) است.\nبرای رسیدن به این مجموعه می‌توانید از مترو استفاده کنید و در ایستگاه مترو ائل گلی پیاده شوید یا خود را به بلوار ائل گلی برسانید.\nبخوانید از: گذری به خانه های قدیمی تبریز : 17 عمارت باشکوه تاریخی', 38.0309882, 46.3534681, '2026-07-30 20:12:02', '2026-07-30 20:17:09'),
	(4, '47129d1f-d78a-4d2b-8a54-b3288d03492e', 25, 'مقبره الشعرا', 'تبریز شهر شاعران و عاشقان به‌نام است. به همین خاطر تعداد زیادی از شاعران فقید سرزمین ما در این شهر و در یک محل دفن هستند. مقبره الشعرا محل آرامگاه ابدی شاعران و ادیبانی از جمله اسدی طوسی، خاقانی شروانی، شاهپور نیشابوری، لسانی شیرازی، شاعر نامی شهریار و تعداد زیادی از شاعران دیگر است. علما و افراد دیگری نیز در این محوطه آرام گرفته‌اند از جمله هفت خواهران، میرزا شفیع مستوفی، دکتر مهدی روشن ضمیر و …. طبق گفته‌های تاریخی، نزدیک به ۴۰۰ تن از بزرگان فرهنگ و علم و ادب در محوطه آرامستان دفن شده‌اند.\nمقب', 'تبریز شهر شاعران و عاشقان به‌نام است. به همین خاطر تعداد زیادی از شاعران فقید سرزمین ما در این شهر و در یک محل دفن هستند. مقبره الشعرا محل آرامگاه ابدی شاعران و ادیبانی از جمله اسدی طوسی، خاقانی شروانی، شاهپور نیشابوری، لسانی شیرازی، شاعر نامی شهریار و تعداد زیادی از شاعران دیگر است. علما و افراد دیگری نیز در این محوطه آرام گرفته‌اند از جمله هفت خواهران، میرزا شفیع مستوفی، دکتر مهدی روشن ضمیر و …. طبق گفته‌های تاریخی، نزدیک به ۴۰۰ تن از بزرگان فرهنگ و علم و ادب در محوطه آرامستان دفن شده‌اند.\nمقبره الشعرا در محله سرخاب تبریز قرار دارد و در گذشته به قبرستان سرخاب معروف بوده است؛ اما بعد از دفن تعدادی از شاعران در این آرامستان، نام این منطقه به مقبره الشعرا تغییر پیدا کرد و حالا یکی از جاهای دیدنی آذربایجان شرقی است. البته قبور این علما و ادیبان در سالیان طولانی تقریبا از بین رفته است و حالا تنها بنای یادبودی در این محوطه قرار دارد که شامل آرامگاه شهریار تبریزی است. برای رسیدن به مقبره الشعرا باید خود را به خیابان ثقه الاسلام و تکیه حیدر برسانید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:17:17'),
	(5, '4be86802-b358-4227-ac22-fed1cfd8d560', 25, 'رصدخانه مراغه', 'رصدخانه مراغه یکی از مشهورترین جاهای دیدنی آذربایجان شرقی است. این رصدخانه که بعد از حمله مغول‌ها و به تلاش خواجه نصیرالدین طوسی، نجم‌الدین کاتبی و فخرالدین مراغه‌ای و با حمایت هلاکوخان ساخته شد،‌ تا چندین صده قبل‌تر، بزرگترین مرکز علمی جهان اسلام بود. امروزه تنها بخش‌های معدودی از این رصدخانه باقی‌مانده است.\nرصدخانه مراغه روی تپه‌ای با ارتفاع ۱۱۰ متر در بخش غربی مراغه قرار گرفته است. برای رسیدن به این رصدخانه باید از بلوار پاسداران به بلوار ولیعصر برسید و سپس وارد جاده رصدخانه شوید.\nبخوانید از:', 'رصدخانه مراغه یکی از مشهورترین جاهای دیدنی آذربایجان شرقی است. این رصدخانه که بعد از حمله مغول‌ها و به تلاش خواجه نصیرالدین طوسی، نجم‌الدین کاتبی و فخرالدین مراغه‌ای و با حمایت هلاکوخان ساخته شد،‌ تا چندین صده قبل‌تر، بزرگترین مرکز علمی جهان اسلام بود. امروزه تنها بخش‌های معدودی از این رصدخانه باقی‌مانده است.\nرصدخانه مراغه روی تپه‌ای با ارتفاع ۱۱۰ متر در بخش غربی مراغه قرار گرفته است. برای رسیدن به این رصدخانه باید از بلوار پاسداران به بلوار ولیعصر برسید و سپس وارد جاده رصدخانه شوید.\nبخوانید از: بهترین سوغاتی های تبریز', 37.3958672, 46.2092839, '2026-07-30 20:12:02', '2026-07-30 20:17:19'),
	(6, 'a79a976f-9edb-43d8-ac04-d00e0ccb718f', 25, 'کلیسای چوپان', 'کلیسای چوپان که نام دیگر آن کلیسای آندره وروتی مقدس است، یکی از کلیساهای ارمنی آذربایجان شرقی است که در غرب جلفا و در فاصله بسیار کمی از رودخانه ارس قرار دارد. ساخت کلیسای چوپان مربوط به دوره صفویه است و طبق روایت‌ها، دلیل اینکه اسم این کلیسا چوپان است این است که در آن زمان، چوپان‌های ارمنی در این محل عبادت می‌کردند و دو برادر این کلیسا و کلیسای جفت آن در آن سوی رود ارس را بنا کردند. البته متاسفانه جفت دیگر کلیسا تخریب شده است.\nاین کلیسا در فاصله ۷ کیلومتری غرب جلفا قرار دارد و تقریبا با ۲۰ دقیق', 'کلیسای چوپان که نام دیگر آن کلیسای آندره وروتی مقدس است، یکی از کلیساهای ارمنی آذربایجان شرقی است که در غرب جلفا و در فاصله بسیار کمی از رودخانه ارس قرار دارد. ساخت کلیسای چوپان مربوط به دوره صفویه است و طبق روایت‌ها، دلیل اینکه اسم این کلیسا چوپان است این است که در آن زمان، چوپان‌های ارمنی در این محل عبادت می‌کردند و دو برادر این کلیسا و کلیسای جفت آن در آن سوی رود ارس را بنا کردند. البته متاسفانه جفت دیگر کلیسا تخریب شده است.\nاین کلیسا در فاصله ۷ کیلومتری غرب جلفا قرار دارد و تقریبا با ۲۰ دقیقه رانندگی می‌توانید به این کلیسای تاریخی و زیبا برسید.', 38.9754477, 45.5727657, '2026-07-30 20:12:02', '2026-07-30 20:17:21'),
	(7, '8c7cfb3a-6c4e-4b08-9b32-9fd98ff64f6e', 25, 'روستای کندوان', 'روستای سنگی کندوان ، یکی از روستاهای خاص ایران است که در آذربایجان شرقی قرار دارد. دلیل خاص بودن این روستا، خانه‌هایی است که در دل کوه کنده شده‌اند و هنوز هم ساکنین روستا در همین خانه‌ها سکونت دارند. کندوان با داشتن آب و هوای خنک و معتدل در تابستان یکی از مقاصد اصلی سفر در تابستان است.\nبرای اجاره سوئیت در کندوان کلیک کنید.\nکندوان در جنوب تبریز و در منطقه سهند قرار دارد. برای رسیدن به کندوان باید ابتدا خود را به تبریز و اسکو برسانید و سپس وارد مسیر کندوان شوید. راستی،‌ حواستان باشد که حتی در تابس', 'روستای سنگی کندوان ، یکی از روستاهای خاص ایران است که در آذربایجان شرقی قرار دارد. دلیل خاص بودن این روستا، خانه‌هایی است که در دل کوه کنده شده‌اند و هنوز هم ساکنین روستا در همین خانه‌ها سکونت دارند. کندوان با داشتن آب و هوای خنک و معتدل در تابستان یکی از مقاصد اصلی سفر در تابستان است.\nبرای اجاره سوئیت در کندوان کلیک کنید.\nکندوان در جنوب تبریز و در منطقه سهند قرار دارد. برای رسیدن به کندوان باید ابتدا خود را به تبریز و اسکو برسانید و سپس وارد مسیر کندوان شوید. راستی،‌ حواستان باشد که حتی در تابستان، حتما لباس گرم همراه داشته باشید تا در صورت سرد شدن هوا، به مشکل نخورید.', 37.7371656, 47.8051604, '2026-07-30 20:12:02', '2026-07-30 20:17:23'),
	(8, 'efb373e8-de08-4dce-9356-b77314890d6a', 25, 'مسجد کبود تبریز', 'مسجد کبود تبریز که حالا در میانه شهر قرار دارد، در قرن ۹ هجری قمری ساخته شده است. نام اصلی این مسجد در زمان ساخت، عمارت مظفریه بوده است. البته زمانه خیلی با این مسجد مهربان نبود و بخش زیادی از آن در قرن‌های گذشته تخریب شده بود. دلیل اصلی تخریب اما زلزله‌ای بود که در سال ۱۱۸۵ شمسی گنبد و مناره‌های مسجد را فرو ریزاند. اما بعد از نزدیک به دو قرن و در سال ۱۳۱۸، بخش‌های تخریب شده بنا مجددا ساخته شد و تعمیر و مرمت کاشی‌کاری‌ها نیز همچنان ادامه دارد.\nمسجد کبود در مرکز شهر تبریز و نزدیک به میدان ساعت و ', 'مسجد کبود تبریز که حالا در میانه شهر قرار دارد، در قرن ۹ هجری قمری ساخته شده است. نام اصلی این مسجد در زمان ساخت، عمارت مظفریه بوده است. البته زمانه خیلی با این مسجد مهربان نبود و بخش زیادی از آن در قرن‌های گذشته تخریب شده بود. دلیل اصلی تخریب اما زلزله‌ای بود که در سال ۱۱۸۵ شمسی گنبد و مناره‌های مسجد را فرو ریزاند. اما بعد از نزدیک به دو قرن و در سال ۱۳۱۸، بخش‌های تخریب شده بنا مجددا ساخته شد و تعمیر و مرمت کاشی‌کاری‌ها نیز همچنان ادامه دارد.\nمسجد کبود در مرکز شهر تبریز و نزدیک به میدان ساعت و بازار بزرگ قرار دارد. این مسجد در تقاطع خیابان امام و خیابان خاقانی قرار دارد و هم با خودروی شخصی و هم با مترو و حمل‌ونقل عمومی می‌توانید به این مسجد سر بزنید.\nبخوانید از: رسوم و آئین های سنتی مردم تبریز', 38.0736335, 46.3010815, '2026-07-30 20:12:02', '2026-07-30 20:17:25'),
	(9, 'e6cc2760-ac74-47ff-b177-718592c0c40d', 25, 'گنبد کبود مراغه', 'یکی از جاهای دیدنی آذربایجان شرقی، گنبد کبود مراغه است. این گنبد یکی از آثار ملی است که از زمان سلجوقیان باقی‌مانده است. البته بعضی از اسناد می‌گویند این گنبد مربوط به زمان حمله مغولان و در واقع آرامگاه مادر هلاکوخان است؛ اما این موضوع هیچ‌وقت تایید نشده است.\nبرای رسیدن به گنبد کبود مراغه کافیست خود را به مرکز شهر مراغه برسانید. مسیر ورودی این مجموعه از خیابان موسوی است.', 'یکی از جاهای دیدنی آذربایجان شرقی، گنبد کبود مراغه است. این گنبد یکی از آثار ملی است که از زمان سلجوقیان باقی‌مانده است. البته بعضی از اسناد می‌گویند این گنبد مربوط به زمان حمله مغولان و در واقع آرامگاه مادر هلاکوخان است؛ اما این موضوع هیچ‌وقت تایید نشده است.\nبرای رسیدن به گنبد کبود مراغه کافیست خود را به مرکز شهر مراغه برسانید. مسیر ورودی این مجموعه از خیابان موسوی است.', 37.3902237, 46.2392058, '2026-07-30 20:12:02', '2026-07-30 20:17:28'),
	(10, '70189ab7-0023-4ee6-9b2a-0bf4a5d17afb', 25, 'معبد مهر مراغه؛ از ناشناخته‌ترین جاهای دیدنی آذربایجان شرقی', 'معبد مهر مراغه، یکی از اولین معابد و عبادتگاه‌های ایران است که به زمان اشکانیان یا حتی قبل از آن برمی‌گردد؛ نشانه‌هایی که از قبرستان این محوطه کشف شده است نشان از عصر آهن دارند. این معبد که پرستشگاه مهرپرستان (آیین پرستش خورشید) بوده است، در یک محوطه بزرگ با چندین بخش مختلف از جمله آرامستان، عبادتگاه، اصطبل و … قرار دارد. معبد مهر یک معبد زیرزمینی است که در دل زمین ایجاد شده است و با وجود چندین خاک‌برداری که انجام شده، تنها بخشی از آن مشخص شده است.\nمعبد مهر در بخش جنوبی مراغه و در روستای ورجوی ق', 'معبد مهر مراغه، یکی از اولین معابد و عبادتگاه‌های ایران است که به زمان اشکانیان یا حتی قبل از آن برمی‌گردد؛ نشانه‌هایی که از قبرستان این محوطه کشف شده است نشان از عصر آهن دارند. این معبد که پرستشگاه مهرپرستان (آیین پرستش خورشید) بوده است، در یک محوطه بزرگ با چندین بخش مختلف از جمله آرامستان، عبادتگاه، اصطبل و … قرار دارد. معبد مهر یک معبد زیرزمینی است که در دل زمین ایجاد شده است و با وجود چندین خاک‌برداری که انجام شده، تنها بخشی از آن مشخص شده است.\nمعبد مهر در بخش جنوبی مراغه و در روستای ورجوی قرار دارد. برای رسیدن به این معبد خارق‌العاده باید از کمربندی جنوبی مراغه به سمت ورجوی حرکت کنید.\nبخوانید از: بهترین مراکز خرید تبریز ؛ از مرکز خرید اطلس تا پیاده راه شهریار', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:17:38'),
	(11, '89384525-86bd-494f-b8f4-e73329bb47af', 25, 'داش قلعه سی و قلعه چای عجب شیر', 'قلعه چای و داش قلعه سی، از زیباترین جاهای دیدنی آذربایجان شرقی هستند که در منطقه عجب شیر قرار دارند. این منطق کوهستانی-دره‌ای شامل چندین قلعه و بقایای آن‌ها می‌شوند و با داشتن طبیعت چشم‌گیر، یکی از زیباترین مقاصد سفر تابستانی هستند.\nبرای رسیدن به این مناطق و بازدید از نقاط مختلف آن‌ها، نیاز به حداقل یک روز کامل دارید. در این مسیر باید ابتدا خود را به مرکز عجب شیر برسانید و سپس به سمت شرق و روستای قوزلوجه حرکت کنید. در این مسیر سد قلعه چای را نیز فراموش نکنید.', 'قلعه چای و داش قلعه سی، از زیباترین جاهای دیدنی آذربایجان شرقی هستند که در منطقه عجب شیر قرار دارند. این منطق کوهستانی-دره‌ای شامل چندین قلعه و بقایای آن‌ها می‌شوند و با داشتن طبیعت چشم‌گیر، یکی از زیباترین مقاصد سفر تابستانی هستند.\nبرای رسیدن به این مناطق و بازدید از نقاط مختلف آن‌ها، نیاز به حداقل یک روز کامل دارید. در این مسیر باید ابتدا خود را به مرکز عجب شیر برسانید و سپس به سمت شرق و روستای قوزلوجه حرکت کنید. در این مسیر سد قلعه چای را نیز فراموش نکنید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:17:49'),
	(12, '3b1aec40-c11a-4dc0-a9ed-410232fe9940', 25, 'قلعه ضحاک هشترود', 'در بخش هشترود آذربایجان شرقی،‌ قلعه‌ای در میان کوه قرار دارد که به اساطیر ایرانی نسبت داده می‌شود. قلعه ضحاک که بر بلندای یک کوه در جنوب شرقی هشترود قرار دارد، یادآور داستان ضحاک ماردوش شاهنامه است. این قلعه طبیعت و تاریخ و زیبایی را یکجا دارد و تقریبا هر بیننده‌ای را مجذوب خود مي‌کند.\nبرای رسیدن به قلعه ضحاک باید ابتدا به هشترود برسید و سپس به علی آباد سفلی بروید. مسیر علی آباد را به سمت جنوب ادامه دهید و در میانه مسیر با کمک تابلوها خود را روستای عربلو برسانید. البته برای رسیدن به قلعه باید مس', 'در بخش هشترود آذربایجان شرقی،‌ قلعه‌ای در میان کوه قرار دارد که به اساطیر ایرانی نسبت داده می‌شود. قلعه ضحاک که بر بلندای یک کوه در جنوب شرقی هشترود قرار دارد، یادآور داستان ضحاک ماردوش شاهنامه است. این قلعه طبیعت و تاریخ و زیبایی را یکجا دارد و تقریبا هر بیننده‌ای را مجذوب خود مي‌کند.\nبرای رسیدن به قلعه ضحاک باید ابتدا به هشترود برسید و سپس به علی آباد سفلی بروید. مسیر علی آباد را به سمت جنوب ادامه دهید و در میانه مسیر با کمک تابلوها خود را روستای عربلو برسانید. البته برای رسیدن به قلعه باید مسیر زیادی را پیاده طی کنید پس حتما در ابتدای روز سفر خود را شروع کنید و تجهیزات و راهنما همراه داشته باشید.\nبخوانید از: 12 غذای محلی و سنتی شهر تبریز', 37.3851455, 47.1672220, '2026-07-30 20:12:02', '2026-07-30 20:17:51'),
	(13, '25642679-6940-415b-bf59-ad8d56733edb', 25, 'منطقه باستانی کاغذ کنان میانه', 'کاغذ کنان یکی از قدیمی‌ترین مناطق ایران است که در بخش شرقی شهرستان میانه قرار دارد. دلیل نام‌گذاری این منطقه این بوده است که در زمان‌های دور (ابتدای ورود اسلام تا زمان حمله مغولان) این منطقه به ساخت کاغذ معروف بوده است و ساکنان محلی آن در کارگاه‌های خانگی که به کاغذخانه معروف بوده است به ساخت کاغذ مشغول بودند.\nکاغذ کنان در حال حاضر منطقه‌ای حفاظت شده است که شامل انواع گونه‌های گیاهی و جانوری خاص می‌شود. برای رسیدن به این منطقه باید ابتدا از میانه خود را به روستای آقکند برسانید و سپس وارد مناطق ط', 'کاغذ کنان یکی از قدیمی‌ترین مناطق ایران است که در بخش شرقی شهرستان میانه قرار دارد. دلیل نام‌گذاری این منطقه این بوده است که در زمان‌های دور (ابتدای ورود اسلام تا زمان حمله مغولان) این منطقه به ساخت کاغذ معروف بوده است و ساکنان محلی آن در کارگاه‌های خانگی که به کاغذخانه معروف بوده است به ساخت کاغذ مشغول بودند.\nکاغذ کنان در حال حاضر منطقه‌ای حفاظت شده است که شامل انواع گونه‌های گیاهی و جانوری خاص می‌شود. برای رسیدن به این منطقه باید ابتدا از میانه خود را به روستای آقکند برسانید و سپس وارد مناطق طبیعی و کوهستانی اطراف شوید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:18:02'),
	(14, '1dfec05d-248c-4480-91a1-3bd889fabe45', 25, 'آبشار آسیاب خرابه', 'آبشار آسیاب خرابه یکی از زیباترین جاهای دیدنی آذربایجان شرقی است. این آبشار در شهرستان جلفا قرار دارد. آبشار آسیاب خرابه ارتفاع کمی دارد اما طول آن و البته حوضچه‌ای که به واسطه ریزش آب در پایین آن تشکیل شده است، منظره‌ای چشم‌گیر را رقم زده است.\nبرای رسیدن به آبشار آسیاب خرابه باید از جلفا به سمت شرق حرکت کنید. پس از گذشت از مرزاد با کمک تابلو راهنما وارد جاده آبشار آسیاب خرابه شوید. در انتهای مسیر نیز باید بخشی را به ‌صورت پیاده طی کنید تا به آبشار برسید.', 'آبشار آسیاب خرابه یکی از زیباترین جاهای دیدنی آذربایجان شرقی است. این آبشار در شهرستان جلفا قرار دارد. آبشار آسیاب خرابه ارتفاع کمی دارد اما طول آن و البته حوضچه‌ای که به واسطه ریزش آب در پایین آن تشکیل شده است، منظره‌ای چشم‌گیر را رقم زده است.\nبرای رسیدن به آبشار آسیاب خرابه باید از جلفا به سمت شرق حرکت کنید. پس از گذشت از مرزاد با کمک تابلو راهنما وارد جاده آبشار آسیاب خرابه شوید. در انتهای مسیر نیز باید بخشی را به ‌صورت پیاده طی کنید تا به آبشار برسید.', 38.8583014, 45.8567649, '2026-07-30 20:12:02', '2026-07-30 20:18:05'),
	(15, '4fe838b0-3db7-45df-a6dc-07e9ca76e9a8', 25, 'کوه عینالی', 'کوه عینالی پربازدید‌ترین کوه شهر تبریز است. عینالی در بخش شمالی تبریز قرار دارد. دلیل شهرت این کوه، نیروگاه توربین بادی است که در بالای آن قرار دارد. البته وجود دریاچه، منطقه تفریحی و تله کابین نیز در محبوبیت این منطقه بین گردشگران بی‌تاثیر نیست. از جاذبه‌های این منطقه می‌توانیم به باغ پرندگان، تفرجگاه، امام‌زادگان عین‌علی و زین‌علی (عون ابن علی و زین ابن علی)، تله کابین تبریز و … اشاره کنیم.\nبرای رسیدن به عینالی باید خود را به بلوار ایده لو برسانید و پس از خروج از بافت شهر، به منطقه تفریحی گردش', 'کوه عینالی پربازدید‌ترین کوه شهر تبریز است. عینالی در بخش شمالی تبریز قرار دارد. دلیل شهرت این کوه، نیروگاه توربین بادی است که در بالای آن قرار دارد. البته وجود دریاچه، منطقه تفریحی و تله کابین نیز در محبوبیت این منطقه بین گردشگران بی‌تاثیر نیست. از جاذبه‌های این منطقه می‌توانیم به باغ پرندگان، تفرجگاه، امام‌زادگان عین‌علی و زین‌علی (عون ابن علی و زین ابن علی)، تله کابین تبریز و … اشاره کنیم.\nبرای رسیدن به عینالی باید خود را به بلوار ایده لو برسانید و پس از خروج از بافت شهر، به منطقه تفریحی گردشگری عینالی می‌رسید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:18:14'),
	(16, '7c8cd120-56fa-4c50-89af-e0c943aafe4b', 25, 'جنگل ارسباران', 'جنگل ارسباران که معروف‌ترین منطقه جنگلی آذربایجان شرقی است، به قدری زیباست که به یکی از محبوب‌ترین جاهای دیدنی آذربایجان شرقی تبدیل شده است. این جنگل در بخش شمالی استان قرار دارد. شهرهای کلیبر،‌ سیران، احمدآباد،‌ خدا آفرین و چندین روستای دیگر در این منطقه جنگلی قرار دارند.\nبرای دیدن جنگل‌های ارسباران می‌توانید خود را به یکی از شهرهای شمالی استان آذربایجان شرقی برسانید و از زیبایی بی‌نظیر این منطقه حفاظت شده جنگلی لذت ببرید. با اجاره سوئیت در کلیبر می‌توانید سفر ساده‌تری برای بازدید از جنگل ارسبا', 'جنگل ارسباران که معروف‌ترین منطقه جنگلی آذربایجان شرقی است، به قدری زیباست که به یکی از محبوب‌ترین جاهای دیدنی آذربایجان شرقی تبدیل شده است. این جنگل در بخش شمالی استان قرار دارد. شهرهای کلیبر،‌ سیران، احمدآباد،‌ خدا آفرین و چندین روستای دیگر در این منطقه جنگلی قرار دارند.\nبرای دیدن جنگل‌های ارسباران می‌توانید خود را به یکی از شهرهای شمالی استان آذربایجان شرقی برسانید و از زیبایی بی‌نظیر این منطقه حفاظت شده جنگلی لذت ببرید. با اجاره سوئیت در کلیبر می‌توانید سفر ساده‌تری برای بازدید از جنگل ارسباران و جاهای دیدنی آذربایجان شرقی داشته باشید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:18:23'),
	(17, 'd5126afe-193d-4ce1-8f5d-d1a309d779a1', 25, 'روستای حیله ور', 'آذربایجان شرقی در است از انواع جاذبه‌های سنگی؛ مانند روستاهایی که در قرون گذشته در دل سنگ کنده شده‌اند، معابد ساخته شده در دل زمین یا نگاره‌های سنگی مختلف. روستای حیله ور نیز یکی از این جاذبه‌های تاریخی است که خانه‌های آن در دل کوه کنده شده‌اند. قدمت این روستا تقریبا به دوره ایلخانی و صفوی بر‌می‌گردد. حیله ور در شهرستان اسکو و در فاصله ۱۸ کیلومتری آن قرار دارد. فاصله حیله ور تا روستای معروف کندوان تنها ۲ کیلومتر است اما گردشگران کمتری از وجود آن خبر دارند.\nخانه‌های روستای حیله ور در دل زمین و به', 'آذربایجان شرقی در است از انواع جاذبه‌های سنگی؛ مانند روستاهایی که در قرون گذشته در دل سنگ کنده شده‌اند، معابد ساخته شده در دل زمین یا نگاره‌های سنگی مختلف. روستای حیله ور نیز یکی از این جاذبه‌های تاریخی است که خانه‌های آن در دل کوه کنده شده‌اند. قدمت این روستا تقریبا به دوره ایلخانی و صفوی بر‌می‌گردد. حیله ور در شهرستان اسکو و در فاصله ۱۸ کیلومتری آن قرار دارد. فاصله حیله ور تا روستای معروف کندوان تنها ۲ کیلومتر است اما گردشگران کمتری از وجود آن خبر دارند.\nخانه‌های روستای حیله ور در دل زمین و به‌صورت دالان‌های تو در تو و مرتبط ساخته شده‌اند و در نگاه اول قابل تشخیص نیستند. اما وقتی نزدیک‌تر می‌شوید می‌توانید ورودی هر دالان را ببینید. برای رسیدن به حیله ور باید از روستای کندوان در حدود ۲ کیلومتر به سمت غرب حرکت کنید و برای دیدن منازل باستانی باید مسافتی را پیاده طی کنید.', 37.8097215, 46.2304433, '2026-07-30 20:12:02', '2026-07-30 20:18:25'),
	(18, 'dde5fc25-3c6b-4e0d-8245-afa8696ead00', 25, 'قله سهند و دامنه‌های سرسبزش', 'کوه سهند یکی از بزرگترین کوه‌های آتشفشانی ایران است که در حال حاضر غیر فعال است. قله سهند ۳۷۰۷ متر ارتفاع دارد و یکی از مهم‌ترین مناطق طبیعی ایران و آذربایجان است. زیبایی و طبیعت بی‌نظیر این منطقه، باعث شده است تا نام دیگر سهند، عروس کوه‌های ایران باشد.\nبهترین فصل سفر به قله و دامنه‌های سهند فصل بهار و تابستان است که هوا در معتدل‌ترین حالت خود قرار دارد. همچنین در این فصول دشت‌های اطراف منطقه پر می‌شوند از گل و گیاهان سرسبز و رنگارنگ و جلوه‌ای زیبا را برای مسافران رقم می‌زنند. برای رسیدن به منطق', 'کوه سهند یکی از بزرگترین کوه‌های آتشفشانی ایران است که در حال حاضر غیر فعال است. قله سهند ۳۷۰۷ متر ارتفاع دارد و یکی از مهم‌ترین مناطق طبیعی ایران و آذربایجان است. زیبایی و طبیعت بی‌نظیر این منطقه، باعث شده است تا نام دیگر سهند، عروس کوه‌های ایران باشد.\nبهترین فصل سفر به قله و دامنه‌های سهند فصل بهار و تابستان است که هوا در معتدل‌ترین حالت خود قرار دارد. همچنین در این فصول دشت‌های اطراف منطقه پر می‌شوند از گل و گیاهان سرسبز و رنگارنگ و جلوه‌ای زیبا را برای مسافران رقم می‌زنند. برای رسیدن به منطقه سهند باید خود را به جنوب تبریز برسانید. مسیرهای مختلفی برای رسیدن به این منطقه وجود دارد که با کمک مسیریاب‌ها یا افراد محلی می‌توانید بهترین مسیر را پیدا کنید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:18:36'),
	(19, 'f256aefa-f803-49d7-86b5-20b2a16b1ce0', 25, 'آلاداغ لار (کوه رنگی)', 'کوه‌های رنگی رشته کوه‌هایی هستند که بخش بزرگی از شمال غرب و حتی شرق ایران را در برمی‌گیرند. در آذربایجان شرقی و زنجان، بخش بزرگی از این کوه‌های رنگی قرار دارد که به آلاداغ لار معروف هستند. دلیل رنگی بودن این کوه‌ها وجود مواد معدنی مختلف در خاک فشرده این کوه‌ها و اکسید شدن این مواد در تماس با اکسیژن هوا است.\nبرای رسیدن به کوه‌های آلاداغ لار می‌توانید مسیر خود را از زنجان به سمت تبریز شروع کنید و در مسیر از این منظره زیبا لذت ببرید. همچنین پس از عبور از تبریز و در مسیر به سمت اهر نیز بخش‌های از کو', 'کوه‌های رنگی رشته کوه‌هایی هستند که بخش بزرگی از شمال غرب و حتی شرق ایران را در برمی‌گیرند. در آذربایجان شرقی و زنجان، بخش بزرگی از این کوه‌های رنگی قرار دارد که به آلاداغ لار معروف هستند. دلیل رنگی بودن این کوه‌ها وجود مواد معدنی مختلف در خاک فشرده این کوه‌ها و اکسید شدن این مواد در تماس با اکسیژن هوا است.\nبرای رسیدن به کوه‌های آلاداغ لار می‌توانید مسیر خود را از زنجان به سمت تبریز شروع کنید و در مسیر از این منظره زیبا لذت ببرید. همچنین پس از عبور از تبریز و در مسیر به سمت اهر نیز بخش‌های از کوه‌های رنگی زیبا وجود دارد که می‌توانید از نزدیک از آن‌ها دیدن کنید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:18:43'),
	(20, '00a8a318-fa08-473e-9d16-dcf43bcbd914', 25, 'صخره‌های سیلدیریم', 'یکی از جاهای دیدنی آذربایجان شرقی که محبوب صخره نوردان است، صخره‌های سیلدیریم در بخش زنوز شهرستان مرند است. این صخره‌ها که ساختار عمودی و خاصی دارند، یکی از محبوب‌ترین مقاصد برای صخره‌نوردان هستند.\nبرای رسیدن به این صخره‌ها باید خود را به میانه و روستای زنوز برسانید. فراموش نکنید که برای صخره‌نوردی باید حتما دانش و مهارت لازم را در کنار امکانات کامل داشته باشید.', 'یکی از جاهای دیدنی آذربایجان شرقی که محبوب صخره نوردان است، صخره‌های سیلدیریم در بخش زنوز شهرستان مرند است. این صخره‌ها که ساختار عمودی و خاصی دارند، یکی از محبوب‌ترین مقاصد برای صخره‌نوردان هستند.\nبرای رسیدن به این صخره‌ها باید خود را به میانه و روستای زنوز برسانید. فراموش نکنید که برای صخره‌نوردی باید حتما دانش و مهارت لازم را در کنار امکانات کامل داشته باشید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:18:51'),
	(21, '6bbcf00c-f1aa-463b-8512-bd0ed30c53b7', 25, 'آبشار بلوکان میانه', 'یکی دیگر از جاذبه‌های دیدنی شهرستان میانه، آبشار بلوکان است. این آبشار در نزدیکی روستانی بلوکان و در وسط یک دره قرار دارد. ارتفاع آبشار بلوکان حدود ۱۰ متر است و پایین آن حوضچه کوچکی از آب تشکیل شده است که در تمام فصول سال آب خنک و حتی سردی دارد.\nبرای رسیدن به این آبشار باید ابتدا خود را به میانه و روستان بلوکان برسانید و سپس مسیر روستا تا آبشار را پیاده طی کنید. این مسیر در حدود ۲ ساعت پیاده روی دارد.\nبخوانید از: راهنمای سفر به تبریز ، شهر تاریخی و دیار فرهنگ و هنر ایران', 'یکی دیگر از جاذبه‌های دیدنی شهرستان میانه، آبشار بلوکان است. این آبشار در نزدیکی روستانی بلوکان و در وسط یک دره قرار دارد. ارتفاع آبشار بلوکان حدود ۱۰ متر است و پایین آن حوضچه کوچکی از آب تشکیل شده است که در تمام فصول سال آب خنک و حتی سردی دارد.\nبرای رسیدن به این آبشار باید ابتدا خود را به میانه و روستان بلوکان برسانید و سپس مسیر روستا تا آبشار را پیاده طی کنید. این مسیر در حدود ۲ ساعت پیاده روی دارد.\nبخوانید از: راهنمای سفر به تبریز ، شهر تاریخی و دیار فرهنگ و هنر ایران', 37.6862180, 47.4796688, '2026-07-30 20:12:02', '2026-07-30 20:18:54'),
	(22, 'b4608946-78a4-4606-8eb7-9a925422efd3', 25, 'ترکمانچای', 'منطقه ترکمانچای که بیشتر به دلیل عهدنامه ترکمانچای معروف است، یکی دشت سرسبز و زیبا در جنوب شرقی تبریز و آذربایجان شرقی است. ترکمانچای نیز از روستاهای تابعه شهرستان میانه است. ترکمانچای فاصله کمی تا جاده تاریخی ابریشم دارد و در زمان‌های گذشته از شهرهای مهم ایران بوده است. عقد عهدنامه ترکمانچای در این روستا خود نشان دهنده قدمت و اهمیت تاریخی آن است.\nبرای رسیدن به ترکمانچای باید از تبریز به سمت میانه حرکت کنید (یا بالعکس). سپس در نزدیکی میانه (فاصله ۴۰ کیلومتری شهر میانه) وارد مسیر ترکمانچای شوید.', 'منطقه ترکمانچای که بیشتر به دلیل عهدنامه ترکمانچای معروف است، یکی دشت سرسبز و زیبا در جنوب شرقی تبریز و آذربایجان شرقی است. ترکمانچای نیز از روستاهای تابعه شهرستان میانه است. ترکمانچای فاصله کمی تا جاده تاریخی ابریشم دارد و در زمان‌های گذشته از شهرهای مهم ایران بوده است. عقد عهدنامه ترکمانچای در این روستا خود نشان دهنده قدمت و اهمیت تاریخی آن است.\nبرای رسیدن به ترکمانچای باید از تبریز به سمت میانه حرکت کنید (یا بالعکس). سپس در نزدیکی میانه (فاصله ۴۰ کیلومتری شهر میانه) وارد مسیر ترکمانچای شوید.', 37.5816929, 47.3911101, '2026-07-30 20:12:02', '2026-07-30 20:18:56'),
	(23, '9e232c3e-244d-471f-b32f-204bea8ce0ad', 25, 'آبشار هرگلان', 'آبشار هرگلان یا آبشار شرشر هرگلان، یکی از جاذبه‌های دیدنی آذربایجان شرقی است که در روستان هرگلان شهرستان عجب شیر قرار دارد. نام قدیم روستان هرگلان بهاردشت بود و ممکن است این آبشار را به این نام نیز بشناسند. بهترین فصل سفر به این آبشار مرتفع و زیبا فصل بهار است که آب آبشار در حداکثر مقدار خود است و از ابتدای تابستان مقدار آب کاهش پیدا می‌کند.\nبرای رسیدن به این آبشار باید از عجب شیر به سمت هرگلان بروید و سپس مسیر آبشار را پیاده طی کنید. تقریبا ۲ساعت و ۳۰ دقیقه زمان برای رسیدن به آبشار نیاز دارید.', 'آبشار هرگلان یا آبشار شرشر هرگلان، یکی از جاذبه‌های دیدنی آذربایجان شرقی است که در روستان هرگلان شهرستان عجب شیر قرار دارد. نام قدیم روستان هرگلان بهاردشت بود و ممکن است این آبشار را به این نام نیز بشناسند. بهترین فصل سفر به این آبشار مرتفع و زیبا فصل بهار است که آب آبشار در حداکثر مقدار خود است و از ابتدای تابستان مقدار آب کاهش پیدا می‌کند.\nبرای رسیدن به این آبشار باید از عجب شیر به سمت هرگلان بروید و سپس مسیر آبشار را پیاده طی کنید. تقریبا ۲ساعت و ۳۰ دقیقه زمان برای رسیدن به آبشار نیاز دارید.', 37.6580755, 46.2843357, '2026-07-30 20:12:02', '2026-07-30 20:19:01'),
	(24, '2b090094-953f-448b-bb7d-d2aa815055f0', 25, 'تفرجگاه ماهار', 'تفرجگاه ماهار، یک دشت سرسبز و وسیع، پوشیده از انواع گل و گیاهان مختلف است که هرساله در فصول مختلف سال پذیرای مسافران از نقاط مختلف ایران است. این دشت زیبا یکی از محبوب‌ترین جاهای دیدنی آذربایجان شرقی بین مسافران است. ماهار در روستای زنوز شهرستان مرند قرار دارد. باقت گیاهی زیبا، رودخانه‌های متعدد، آب و هوای معتدل و فضای وسیع، این منطقه را به یکی از پرطرفدارترین مقاصد سفر تابستانی تبدیل کرده است.\nبرای رسیدن به تفرجگاه ماهار باید ابتدا به مرند و زانوز برسید و سپس از افراد محلی آدرس دشت ماهار را بخو', 'تفرجگاه ماهار، یک دشت سرسبز و وسیع، پوشیده از انواع گل و گیاهان مختلف است که هرساله در فصول مختلف سال پذیرای مسافران از نقاط مختلف ایران است. این دشت زیبا یکی از محبوب‌ترین جاهای دیدنی آذربایجان شرقی بین مسافران است. ماهار در روستای زنوز شهرستان مرند قرار دارد. باقت گیاهی زیبا، رودخانه‌های متعدد، آب و هوای معتدل و فضای وسیع، این منطقه را به یکی از پرطرفدارترین مقاصد سفر تابستانی تبدیل کرده است.\nبرای رسیدن به تفرجگاه ماهار باید ابتدا به مرند و زانوز برسید و سپس از افراد محلی آدرس دشت ماهار را بخواهید.', 35.6937251, 51.3861394, '2026-07-30 20:12:02', '2026-07-30 20:19:14'),
	(25, '7eab3f65-5073-4df3-8d60-b359de036b9f', 26, 'دریاچه ارومیه', 'دریاچه ارومیه که زمانی به نام‌های دریاچه شاهی، رضاییه، چیچست، ماتیانوس و اسپوتا شناخته می‌شد، بزرگ‌ترین دریاچه آب شور ایران با مساحت ۶ هزار کیلومتر مربع است. ارومیه ششمین دریاچه بزرگ آب شور دنیا و بزرگ‌ترین دریاچه خاورمیانه بود اما متاسفانه به دلیل استفاده بیش از حد منابع آبی و سدسازی و… خشک شد. تاریخچه دریاچه ارومیه ریشه در روزگار باستان دارد. در دوران هخامنشیان، این دریاچه نه‌تنها بخشی از قلمرو تمدن ایرانیان بود، بلکه نقشی مهم در حمل‌ونقل، ماهیگیری و آبیاری داشت. دریاچه ارومیه در گذشته، زیستگا', 'دریاچه ارومیه که زمانی به نام‌های دریاچه شاهی، رضاییه، چیچست، ماتیانوس و اسپوتا شناخته می‌شد، بزرگ‌ترین دریاچه آب شور ایران با مساحت ۶ هزار کیلومتر مربع است. ارومیه ششمین دریاچه بزرگ آب شور دنیا و بزرگ‌ترین دریاچه خاورمیانه بود اما متاسفانه به دلیل استفاده بیش از حد منابع آبی و سدسازی و… خشک شد. تاریخچه دریاچه ارومیه ریشه در روزگار باستان دارد. در دوران هخامنشیان، این دریاچه نه‌تنها بخشی از قلمرو تمدن ایرانیان بود، بلکه نقشی مهم در حمل‌ونقل، ماهیگیری و آبیاری داشت. دریاچه ارومیه در گذشته، زیستگاه هزاران گونه پرنده فلامینگو و اردک‌ها بود و آب آن به دلیل املاح زیاد، خواص درمانی زیادی داشت.\nآدرس: آذربایجان غربی، ارومیه، پارک ملی دریاچه ارومیه، مرز بین استان‌های آذربایجان شرقی و آذربایجان غربی', 37.7936118, 45.3753617, '2026-07-30 20:12:02', '2026-07-30 20:19:17'),
	(26, 'aff79e73-784b-4196-96be-43e230240971', 26, 'دریاچه و کوه دالامپر ارومیه', 'کوه دالامپر در نقطه صفر مرزی یعنی در مرکز کشور ایران، ترکیه و عراق قرار دارد. این کوه با یخچال‌های چند هزار ساله، دریاچه‌های طبیعی و رودخانه‌های پرآب، یکی از بکرترین جاهای دیدنی استان آذربایجان غربی است. از برف‌آب‌های این کوه، آبشاری بزرگ به نام سوله دوکل تشکیل می‌شود که نمایی جذاب دارد. کوه دالامپر فضای مناسبی برای کوهنوردی در فصل بهار دارد؛ زمانی که ترکیب برف و گل‌های وحشی، مناظری شگفت‌انگیز را خلق می‌کنند. دریاچه دالامپر که به نام محلی مام شیخ نیز شناخته می‌شود، در جنوب غربی ارومیه و نزدیک مر', 'کوه دالامپر در نقطه صفر مرزی یعنی در مرکز کشور ایران، ترکیه و عراق قرار دارد. این کوه با یخچال‌های چند هزار ساله، دریاچه‌های طبیعی و رودخانه‌های پرآب، یکی از بکرترین جاهای دیدنی استان آذربایجان غربی است. از برف‌آب‌های این کوه، آبشاری بزرگ به نام سوله دوکل تشکیل می‌شود که نمایی جذاب دارد. کوه دالامپر فضای مناسبی برای کوهنوردی در فصل بهار دارد؛ زمانی که ترکیب برف و گل‌های وحشی، مناظری شگفت‌انگیز را خلق می‌کنند. دریاچه دالامپر که به نام محلی مام شیخ نیز شناخته می‌شود، در جنوب غربی ارومیه و نزدیک مرز ایران، ترکیه و عراق قرار دارد. آب زلال و سرد این دریاچه از برف‌های کوه سرچشمه می‌گیرد. بهترین زمان بازدید از دریاچه دالامپر برای لذت‌بردن از هوایی مطبوع، اردیبهشت و خرداد است.\nآدرس: آذربایجان غربی، ۴۵ کیلومتری ارومیه، جاده ارومیه به اشنویه، ۳۵ کیلومتری شمال غربی شهر اشنویه', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:19:29'),
	(27, 'c9395fa5-28a0-4483-b128-b05a153897d4', 26, 'دریاچه مارمیشو ارومیه', 'دریاچه مارمیشو هم مانند دریاچه دالامپر در دره‌ای کوهستانی قرار دارد و از جنوب به قله‌های سی‌تاو، قایدوک و چال و از شمال به کوه بایدوست محدود می‌شود. آب دریاچه مارمیشو زلال و هوای اطراف آن در تابستان بسیار خنک است. در اطراف این دریاچه، درختان صنوبر، بلوط و گردو به چشم می‌خورند که مناظر زیبایی را ایجاد کرده‌اند. به علاوه در دریاچه مارمیشو، ماهی قزل‌آلا و پرندگان مهاجر زیادی زندگی می‌کنند.\nآدرس: آذربایجان غربی، ۴۵ کیلومتری غرب ارومیه، روستای مارمیشو', 'دریاچه مارمیشو هم مانند دریاچه دالامپر در دره‌ای کوهستانی قرار دارد و از جنوب به قله‌های سی‌تاو، قایدوک و چال و از شمال به کوه بایدوست محدود می‌شود. آب دریاچه مارمیشو زلال و هوای اطراف آن در تابستان بسیار خنک است. در اطراف این دریاچه، درختان صنوبر، بلوط و گردو به چشم می‌خورند که مناظر زیبایی را ایجاد کرده‌اند. به علاوه در دریاچه مارمیشو، ماهی قزل‌آلا و پرندگان مهاجر زیادی زندگی می‌کنند.\nآدرس: آذربایجان غربی، ۴۵ کیلومتری غرب ارومیه، روستای مارمیشو', 37.5842623, 44.6375411, '2026-07-30 20:12:02', '2026-07-30 20:19:32'),
	(28, '20357839-399f-472c-970a-700cb221b919', 26, 'آبشار سوله دوکل ارومیه', 'آبشار سوله دوکل یکی از زیباترین و مرتفع‌ترین آبشارهای ایران در نزدیکی روستایی به همین نام قرار دارد. این آبشار با ارتفاعی حدود ۴۰ متر و عرض ۱۰ متر، در دامنه کوه دالامپر قرار دارد. نام «سوله دوکل» در زبان کردی به معنای «آبشار دود» بوده که به دلیل پاشیده‌شدن قطرات آب در هوا و ایجاد هاله‌ای از بخار در اطراف آبشار به آن گفته می‌شود. برای دسترسی به آبشار سوله دوکل باید از شهر ارومیه به سمت روستای سوله دوکل حرکت کرده و پس از رسیدن به روستا، حدود ۲۰۰ متر پیاده‌روی کنید.\nآدرس: آذربایجان غربی، ارومیه، بخ', 'آبشار سوله دوکل یکی از زیباترین و مرتفع‌ترین آبشارهای ایران در نزدیکی روستایی به همین نام قرار دارد. این آبشار با ارتفاعی حدود ۴۰ متر و عرض ۱۰ متر، در دامنه کوه دالامپر قرار دارد. نام «سوله دوکل» در زبان کردی به معنای «آبشار دود» بوده که به دلیل پاشیده‌شدن قطرات آب در هوا و ایجاد هاله‌ای از بخار در اطراف آبشار به آن گفته می‌شود. برای دسترسی به آبشار سوله دوکل باید از شهر ارومیه به سمت روستای سوله دوکل حرکت کرده و پس از رسیدن به روستا، حدود ۲۰۰ متر پیاده‌روی کنید.\nآدرس: آذربایجان غربی، ارومیه، بخش سیلوانه، دهستان مرگور، کوه دالامپر', 37.1777473, 44.8714512, '2026-07-30 20:12:02', '2026-07-30 20:19:37'),
	(29, 'd6426ca0-60b1-443e-b511-91ee381c5afb', 26, 'تالاب گلمرز ارومیه', 'یکی از جاذبه‌های طبیعی کمتر شناخته‌شده اما بسیار دیدنی در استان آذربایجان غربی، تالاب گلمرز ارومیه نام دارد. این تالاب در نزدیکی روستای گلمرز واقع شده و در اطراف آن پوشش گیاهی متنوع و چندین چشمه‌ وجود دارد. در فصل بهار و تابستان، این منطقه با وجود شکوفه‌ زیبای درختان و سرسبزی طبیعت، مقصدی عالی برای طبیعت‌گردان می‌شود. در اطراف تالاب گلمرز می‌توانید اتاق‌هایی را برای استراحت و اقامت خود انتخاب کنید. این تالاب زیستگاه مناسبی برای پرندگان مهاجر مانند اردک و غاز وحشی بوده که در فصل پاییز به این منطق', 'یکی از جاذبه‌های طبیعی کمتر شناخته‌شده اما بسیار دیدنی در استان آذربایجان غربی، تالاب گلمرز ارومیه نام دارد. این تالاب در نزدیکی روستای گلمرز واقع شده و در اطراف آن پوشش گیاهی متنوع و چندین چشمه‌ وجود دارد. در فصل بهار و تابستان، این منطقه با وجود شکوفه‌ زیبای درختان و سرسبزی طبیعت، مقصدی عالی برای طبیعت‌گردان می‌شود. در اطراف تالاب گلمرز می‌توانید اتاق‌هایی را برای استراحت و اقامت خود انتخاب کنید. این تالاب زیستگاه مناسبی برای پرندگان مهاجر مانند اردک و غاز وحشی بوده که در فصل پاییز به این منطقه مهاجرت می‌کنند.\nآدرس: ارومیه، خیابان المهدی، جاده ریحان‌آباد', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:19:49'),
	(30, '20f4bbf6-27c8-4345-a878-c49912338e82', 26, 'بندر شرفخانه ارومیه', 'در گذشته بندر شرفخانه ارومیه، مناظری زیبا داشت، به‌طوری که دلتان می‌خواست ساعت‌ها بنشینید و محو زیبایی‌های آن شوید اما متاسفانه امروز دیگر اثری از آن نیست. در بندر شرفخانه، انبارهای بزرگ کالا بود که از طریق قایق‌های عظیم و راه‌آهن به شهرهای دور ارسال می‌شدند.\nآدرس: آذربایجان شرقی، شهرستان شبستر، بخش مرکزی، شهر بندر شرفخانه', 'در گذشته بندر شرفخانه ارومیه، مناظری زیبا داشت، به‌طوری که دلتان می‌خواست ساعت‌ها بنشینید و محو زیبایی‌های آن شوید اما متاسفانه امروز دیگر اثری از آن نیست. در بندر شرفخانه، انبارهای بزرگ کالا بود که از طریق قایق‌های عظیم و راه‌آهن به شهرهای دور ارسال می‌شدند.\nآدرس: آذربایجان شرقی، شهرستان شبستر، بخش مرکزی، شهر بندر شرفخانه', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:19:58'),
	(31, '46702a77-f823-40b2-9820-59df4e6c4217', 26, 'دره قاسملو ارومیه', 'دره قاسملو که به ترکی به نام‌های «خان‌دره‌سی» و «دره شهدا» معروف است، یکی از جاهای دیدنی آذربایجان غربی در ارومیه است. این دره، منطقه‌ای کوهستانی بوده و رودخانه‌هایی مانند باراندوز و شهدا از میان آن می‌گذرند. دره قاسملو زیستگاه گونه‌های مختلف گیاهی و جانوری است و از نظر داشتن باغ‌های سیب شهرت زیادی دارد. در انتهای دره قاسملو، آبشاری با ارتفاع حدود ۱۵ متر قرار دارد که دسترسی به آن از طریق پیاده‌روی در مسیرهای سنگی امکان‌پذیر است.\nآدرس: 35 کیلومتری جنوب ‌غربی ارومیه، جاده ارومیه-اشنویه', 'دره قاسملو که به ترکی به نام‌های «خان‌دره‌سی» و «دره شهدا» معروف است، یکی از جاهای دیدنی آذربایجان غربی در ارومیه است. این دره، منطقه‌ای کوهستانی بوده و رودخانه‌هایی مانند باراندوز و شهدا از میان آن می‌گذرند. دره قاسملو زیستگاه گونه‌های مختلف گیاهی و جانوری است و از نظر داشتن باغ‌های سیب شهرت زیادی دارد. در انتهای دره قاسملو، آبشاری با ارتفاع حدود ۱۵ متر قرار دارد که دسترسی به آن از طریق پیاده‌روی در مسیرهای سنگی امکان‌پذیر است.\nآدرس: 35 کیلومتری جنوب ‌غربی ارومیه، جاده ارومیه-اشنویه', 37.3100965, 45.1168414, '2026-07-30 20:12:02', '2026-07-30 20:20:00'),
	(32, 'cb98253c-62aa-44b2-8955-16fe04513869', 26, 'چشمه آب معدنی کوه زنبیل ارومیه', 'چشمه‌ آب‌ معدنی کوه زنبیل در دامنه­‌ شرقی کوه زنبیل در دهستان نازلو چای قرار دارد. این چشمه به شکل دایره‌ با قطر ۴ متر بوده و از کف آن به‌طور مداوم گاز خارج می‌شود. آب چشمه کوه زنبیل ترکیباتی مانند بی‌کربنات کلسیم، منیزیم، آهن و سولفات دارد که محلی‌ها معتقدند برای درمان دردهای مفصلی و مشکلات پوستی مفید است.\nآدرس: آذربایجان غربی، شهرستان ارومیه، بخش نازلوچای، کوه زنبیل، حدود ۳۰ کیلومتر شمال‌شرقی ارومیه', 'چشمه‌ آب‌ معدنی کوه زنبیل در دامنه­‌ شرقی کوه زنبیل در دهستان نازلو چای قرار دارد. این چشمه به شکل دایره‌ با قطر ۴ متر بوده و از کف آن به‌طور مداوم گاز خارج می‌شود. آب چشمه کوه زنبیل ترکیباتی مانند بی‌کربنات کلسیم، منیزیم، آهن و سولفات دارد که محلی‌ها معتقدند برای درمان دردهای مفصلی و مشکلات پوستی مفید است.\nآدرس: آذربایجان غربی، شهرستان ارومیه، بخش نازلوچای، کوه زنبیل، حدود ۳۰ کیلومتر شمال‌شرقی ارومیه', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:20:17'),
	(33, '70322d94-9f5c-4d82-bb56-43a3ab0154bd', 26, 'بازار ارومیه', 'بازار تاریخی ارومیه در وسط شهر ارومیه، یکی دیگر از جاذبه های دیدنی آذربایجان غربی محسوب می‌شود. قدمت این بازار به دوران صفویه بازمی‌گردد و معماری آن به سبک ایرانی اصیل با گنبدها و طاق‌های آجری است. در بازار ارومیه راسته‌های متنوعی از مسگری و زرگری گرفته تا عطاری، بلورفروشی و چاقوسازی وجود دارد. گردشگران نه تنها برای خرید بلکه برای قدم زدن در محیطی تاریخی به بازار ارومیه می‌آیند. اگر قصد دارید یک روز کامل را به گشت‌وگذار در این بازار اختصاص بدهید، پیشنهاد می‌کنیم از بخش صنایع‌دستی محلی، حتما بازد', 'بازار تاریخی ارومیه در وسط شهر ارومیه، یکی دیگر از جاذبه های دیدنی آذربایجان غربی محسوب می‌شود. قدمت این بازار به دوران صفویه بازمی‌گردد و معماری آن به سبک ایرانی اصیل با گنبدها و طاق‌های آجری است. در بازار ارومیه راسته‌های متنوعی از مسگری و زرگری گرفته تا عطاری، بلورفروشی و چاقوسازی وجود دارد. گردشگران نه تنها برای خرید بلکه برای قدم زدن در محیطی تاریخی به بازار ارومیه می‌آیند. اگر قصد دارید یک روز کامل را به گشت‌وگذار در این بازار اختصاص بدهید، پیشنهاد می‌کنیم از بخش صنایع‌دستی محلی، حتما بازدید کنید.\nآدرس: ارومیه، بافت قدیمی شهر، بین خیابان امام و بعثت', 37.5512923, 45.0749306, '2026-07-30 20:12:02', '2026-07-30 20:20:19'),
	(34, '2bcc748a-6c25-4155-a025-6180e388a70a', 26, 'موزه ارومیه', 'کوله‌بار سفر را جمع می‌کنیم و به سمت یکی از جاهای دیدنی و تاریخی آذربایجان غربی یعنی موزه ارومیه می‌رویم. این موزه با بیش از ۲۶ هزار شی تاریخی و باستانی، یکی از غنی‌ترین موزه‌های ایران به شمار می‌رود و اهمیت تاریخی زیادی دارد. در این مجموعه می‌توانید آثار مربوط به دوره‌های مختلف ایران از ۷۰۰۰ سال قبل از میلاد تا دوران قاجار را مشاهده کنید. بخشی از موزه ارومیه به مردم‌شناسی استان آذربایجان غربی اختصاص دارد تا با سبک زندگی، آداب و رسوم و فرهنگ مردم این منطقه آشنا شوید.\nآدرس: آذربایجان غربی، ارومیه', 'کوله‌بار سفر را جمع می‌کنیم و به سمت یکی از جاهای دیدنی و تاریخی آذربایجان غربی یعنی موزه ارومیه می‌رویم. این موزه با بیش از ۲۶ هزار شی تاریخی و باستانی، یکی از غنی‌ترین موزه‌های ایران به شمار می‌رود و اهمیت تاریخی زیادی دارد. در این مجموعه می‌توانید آثار مربوط به دوره‌های مختلف ایران از ۷۰۰۰ سال قبل از میلاد تا دوران قاجار را مشاهده کنید. بخشی از موزه ارومیه به مردم‌شناسی استان آذربایجان غربی اختصاص دارد تا با سبک زندگی، آداب و رسوم و فرهنگ مردم این منطقه آشنا شوید.\nآدرس: آذربایجان غربی، ارومیه، خیابان دانشکده، روبه‌روی بانک تجارت\nساعت بازدید: هر روز از ۸ صبح تا ۱۷\nهزینه بلیط: 4 هزار تومان', 37.5360366, 45.0661026, '2026-07-30 20:12:02', '2026-07-30 20:20:21'),
	(35, '2939b2e8-c37b-4da5-83a8-e0befc583bca', 26, 'بنای سه گنبد ارومیه', 'اگر به ارومیه سفر کردید، حتما بنای سه گنبد را ببینید. این بنای آجری دایره‌ای در میان کوچه‌های بافت قدیمی شهر قرار گرفته و معماری آن به دوران سلجوقی نسبت داده شده است. در بنای سه‌گنبد ارومیه، کتیبه‌هایی با خطوط نقش برجسته را می‌بینید. بخش پایینی این بنا با سنگ تراش‌خورده و بخش بالایی آن از آجر ساخته شده است. بنیان‌گذار بنای سه گنبد، یکی از حاکمان وقت به نام «شیث قاطه المظفری» بود و این بنا احتمالا روی بقایای یک آتشکده ساخته شده است.\nآدرس: آذربایجان غربی، ارومیه، خیابان جانبازان (استاد برزگر)', 'اگر به ارومیه سفر کردید، حتما بنای سه گنبد را ببینید. این بنای آجری دایره‌ای در میان کوچه‌های بافت قدیمی شهر قرار گرفته و معماری آن به دوران سلجوقی نسبت داده شده است. در بنای سه‌گنبد ارومیه، کتیبه‌هایی با خطوط نقش برجسته را می‌بینید. بخش پایینی این بنا با سنگ تراش‌خورده و بخش بالایی آن از آجر ساخته شده است. بنیان‌گذار بنای سه گنبد، یکی از حاکمان وقت به نام «شیث قاطه المظفری» بود و این بنا احتمالا روی بقایای یک آتشکده ساخته شده است.\nآدرس: آذربایجان غربی، ارومیه، خیابان جانبازان (استاد برزگر)', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:20:34'),
	(36, 'd954fa49-ca91-44e9-87bc-04cf57271a96', 26, 'پیست اسکی خوشاکو ارومیه', 'پیست اسکی خوشاکو، تنها پیست اسکی استان در ۳۰ کیلومتری غرب ارومیه است و یکی از جاهای دیدنی و تفریحی آذربایجان غربی به حساب می‌آید. این پیست امکاناتی مانند سه تله‌ سیژ و یک تله‌ آموزشی (بخشی از پیست اسکی برای آموزش مبتدیان و تازه‌کارها ) دارد. خوشاکو با پوشش گیاهی مناسب در تابستان نیز امکان اسکی روی چمن را فراهم می‌کند. برای رسیدن به پیست خوشاکو می‌توانید از ارومیه به سمت جاده سیلوانا حرکت کنید و پس از عبور از روستای راژان و جاده روستای خوشاکو، به این منطقه تفریحی برسید.\nآدرس: آذربایجان غربی، ۳۰ ک', 'پیست اسکی خوشاکو، تنها پیست اسکی استان در ۳۰ کیلومتری غرب ارومیه است و یکی از جاهای دیدنی و تفریحی آذربایجان غربی به حساب می‌آید. این پیست امکاناتی مانند سه تله‌ سیژ و یک تله‌ آموزشی (بخشی از پیست اسکی برای آموزش مبتدیان و تازه‌کارها ) دارد. خوشاکو با پوشش گیاهی مناسب در تابستان نیز امکان اسکی روی چمن را فراهم می‌کند. برای رسیدن به پیست خوشاکو می‌توانید از ارومیه به سمت جاده سیلوانا حرکت کنید و پس از عبور از روستای راژان و جاده روستای خوشاکو، به این منطقه تفریحی برسید.\nآدرس: آذربایجان غربی، ۳۰ کیلومتری غرب ارومیه، منطقه راژان، روستای خوشاکو\nساعت کاری: ۹ صبح تا ۱۶', 37.4608417, 44.7847406, '2026-07-30 20:12:02', '2026-07-30 20:20:37'),
	(37, '0c85dea0-e44f-4e26-b3c1-01fc4e076484', 26, 'پارک گلها (گوللر باغی) ارومیه', 'در مرکز ارومیه، پارکی سرسبز به نام پارک گل‌ها (گوللر باغی) قرار گرفته که بیش از ۵۰۰ هزار شاخه گل مانند بنفشه، لاله، میخک، کوکب، مینای چمنی و شب‌بو آن را به «فرش هزار رنگ» تبدیل کرده‌اند. رودخانه شهرچایی از میان این پارک می‌گذرد و آرامش فضای آن را دو چندان کرده؛ جایی که صدای جریان آب و عطر گل‌ها فضایی دل‌نشین را می‌سازد. هر سال در فصل بهار، جشنواره گل در پارک گل‌ها برگزار می‌شود و در کارگاه‌های آن، قلمه‌زدن گل را به صورت رایگان آموزش می‌دهند.\nآدرس: ارومیه، محله خطای لو، کنارگذر امام علی، کنار رود', 'در مرکز ارومیه، پارکی سرسبز به نام پارک گل‌ها (گوللر باغی) قرار گرفته که بیش از ۵۰۰ هزار شاخه گل مانند بنفشه، لاله، میخک، کوکب، مینای چمنی و شب‌بو آن را به «فرش هزار رنگ» تبدیل کرده‌اند. رودخانه شهرچایی از میان این پارک می‌گذرد و آرامش فضای آن را دو چندان کرده؛ جایی که صدای جریان آب و عطر گل‌ها فضایی دل‌نشین را می‌سازد. هر سال در فصل بهار، جشنواره گل در پارک گل‌ها برگزار می‌شود و در کارگاه‌های آن، قلمه‌زدن گل را به صورت رایگان آموزش می‌دهند.\nآدرس: ارومیه، محله خطای لو، کنارگذر امام علی، کنار رودخانه شهرچایی', 37.5289940, 45.0543186, '2026-07-30 20:12:02', '2026-07-30 20:20:42'),
	(38, 'c7b20ca9-d3f4-4142-998d-4713efb6d757', 26, 'پارک ائللرباغی ارومیه', 'در لیست جاهای دیدنی آذربایجان غربی در بهار، نام پارک ائللر باغی می‌درخشد. این پارک بزرگ‌ترین پارک ارومیه بوده و مساحتی در حدود ۴۱ هکتار دارد. مسیرهای پیاده‌روی و دوچرخه‌سواری، دریاچه مصنوعی و آب‌نمای مرتفع از بخش‌های جذاب این پارک هستند. قایق‌سواری روی دریاچه، درشکه‌سواری، پیست دوچرخه‌سواری و سالن آمفی‌تئاتر روباز از تفریحات مهم این مکان هستند. کنار رودخانه و فضای باز پارک ائللر باغی، منظره غروب زیبایی دارد که برای عکس‌برداری فوق‌العاده‌ است!\nآدرس: آذربایجان غربی، ارومیه، خیابان والفجر، ساحل رود', 'در لیست جاهای دیدنی آذربایجان غربی در بهار، نام پارک ائللر باغی می‌درخشد. این پارک بزرگ‌ترین پارک ارومیه بوده و مساحتی در حدود ۴۱ هکتار دارد. مسیرهای پیاده‌روی و دوچرخه‌سواری، دریاچه مصنوعی و آب‌نمای مرتفع از بخش‌های جذاب این پارک هستند. قایق‌سواری روی دریاچه، درشکه‌سواری، پیست دوچرخه‌سواری و سالن آمفی‌تئاتر روباز از تفریحات مهم این مکان هستند. کنار رودخانه و فضای باز پارک ائللر باغی، منظره غروب زیبایی دارد که برای عکس‌برداری فوق‌العاده‌ است!\nآدرس: آذربایجان غربی، ارومیه، خیابان والفجر، ساحل رودخانه شهرچایی', 37.5375651, 45.1046695, '2026-07-30 20:12:02', '2026-07-30 20:20:47'),
	(39, '62ef31d8-7dda-41cf-af4b-1cab45d4e737', 26, 'تفرجگاه بند ارومیه', 'بهترین مکان تفریحی آذربایجان غربی از نظر مسافران، بند ارومیه است. این روستای خوش‌آب‌وهوا در نزدیکی ارومیه با طبیعت بکر، رودخانه پرآب، باغ‌های سرسبز و جاذبه‌های تاریخی قرار دارد. مردم بند عمدتا کرد زبان بوده و شغل اصلی آن‌ها زراعت و دامداری است، اما با افزایش توریست‌ها، بسیاری از آنها به صنعت گردشگری روی آورده‌اند. در رستوران‌ها، کافه‌ها و کبابی‌های محلی این تفرجگاه می‌توانید غذایی لذیذ را نوش جان کنید. مراسمی مانند چهارشنبه‌سوری، شب یلدا و عید نوروز در این منطقه برگزار می‌شود که حال‌وهوای قدیمی ', 'بهترین مکان تفریحی آذربایجان غربی از نظر مسافران، بند ارومیه است. این روستای خوش‌آب‌وهوا در نزدیکی ارومیه با طبیعت بکر، رودخانه پرآب، باغ‌های سرسبز و جاذبه‌های تاریخی قرار دارد. مردم بند عمدتا کرد زبان بوده و شغل اصلی آن‌ها زراعت و دامداری است، اما با افزایش توریست‌ها، بسیاری از آنها به صنعت گردشگری روی آورده‌اند. در رستوران‌ها، کافه‌ها و کبابی‌های محلی این تفرجگاه می‌توانید غذایی لذیذ را نوش جان کنید. مراسمی مانند چهارشنبه‌سوری، شب یلدا و عید نوروز در این منطقه برگزار می‌شود که حال‌وهوای قدیمی دارند و سنت‌های گذشته را حفظ می‌کنند.\nآدرس: ارومیه، خیابان بهشتی، جاده بند زیوه', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:20:55'),
	(40, 'c202427e-ee25-43a2-b89f-ca8665600240', 26, 'مسجد جامع ارومیه', 'یکی از آثار تاریخی و مذهبی مهم ارومیه به مسجد جامع تعلق دارد که قدمت آن به عهد سلجوقی برمی‌گردد. این مسجد روی بقایای یک آتشکده زرتشتیان در دوره ساسانی و زمان خسرو پرویز (پادشاه ایرانی) ساخته شده و در سال ۱۳۱۴ در فهرست آثار ملی به ثبت رسید. شبستان مسجد جامع با گنبد سلجوقی و محراب‌های هشت‌ضلعی ساخته شده که در طبقات بالاتر ۱۶ ضلعی می‌شوند و سپس شکل گنبد اصلی را به خود می‌گیرند. معماری مسجد جامع ارومیه برگرفته از معماری مسجدهای دوران اسلامی و ایلخانی است.\nآدرس: ارومیه، محله بازارباش ارومیه، خیابان ب', 'یکی از آثار تاریخی و مذهبی مهم ارومیه به مسجد جامع تعلق دارد که قدمت آن به عهد سلجوقی برمی‌گردد. این مسجد روی بقایای یک آتشکده زرتشتیان در دوره ساسانی و زمان خسرو پرویز (پادشاه ایرانی) ساخته شده و در سال ۱۳۱۴ در فهرست آثار ملی به ثبت رسید. شبستان مسجد جامع با گنبد سلجوقی و محراب‌های هشت‌ضلعی ساخته شده که در طبقات بالاتر ۱۶ ضلعی می‌شوند و سپس شکل گنبد اصلی را به خود می‌گیرند. معماری مسجد جامع ارومیه برگرفته از معماری مسجدهای دوران اسلامی و ایلخانی است.\nآدرس: ارومیه، محله بازارباش ارومیه، خیابان برق، خیابان امام خمینی\nساعت بازدید: هر روز از ۹ صبح تا ۱۹\nهزینه بلیط: 15 هزار تومان', 37.5509359, 45.0756813, '2026-07-30 20:12:02', '2026-07-30 20:20:58'),
	(41, 'd63dbb5b-4bf1-401b-912a-4eb19f36073e', 26, 'مسجد لطفعلی خان ارومیه', 'مسجد لطفعلی خان ارومیه، یکی دیگر از مساجد تاریخی و زیباست که در دوره قاجاریه به دستور لطفعلی خان ساخته شد و به همین دلیل به اسم او نام‌گذاری شده است. نمای بیرونی مسجد لطفعلی خان با کاشی‌کاری‌های رنگی و طراحی جذاب، توجه هر بیننده‌ای را جلب می‌کند. این مسجد به عنوان یکی از مراکز مهم مذهبی و فرهنگی ارومیه، محل برگزاری مراسم‌ مذهبی است.\nآدرس: ارومیه، حافظ، خیابان امام خمینی، خیابان سرداران', 'مسجد لطفعلی خان ارومیه، یکی دیگر از مساجد تاریخی و زیباست که در دوره قاجاریه به دستور لطفعلی خان ساخته شد و به همین دلیل به اسم او نام‌گذاری شده است. نمای بیرونی مسجد لطفعلی خان با کاشی‌کاری‌های رنگی و طراحی جذاب، توجه هر بیننده‌ای را جلب می‌کند. این مسجد به عنوان یکی از مراکز مهم مذهبی و فرهنگی ارومیه، محل برگزاری مراسم‌ مذهبی است.\nآدرس: ارومیه، حافظ، خیابان امام خمینی، خیابان سرداران', 37.5490326, 45.0670648, '2026-07-30 20:12:02', '2026-07-30 20:21:00'),
	(42, '7451f2c2-805d-4bf7-9922-29f6db92b408', 26, 'کلیسای ننه مریم ارومیه', 'کلیسای ننه مریم ارومیه که به اسم‌های کلیسای حضرت مریم، مارت مریم و شرق‌آشور شناخته می‌شود، دومین کلیسای قدیمی جهان بعد از کلیسای بیت‌لحم در فلسطین است. قدمت این بنا به قرن اول میلادی می‌رسد و در ابتدا به‌عنوان آتشکده‌ای زرتشتی ساخته شده بود. پس از ورود مسیحیت به منطقه، این مکان به کلیسا تبدیل شد و در طول تاریخ بارها بازسازی شده است.\nآدرس: ارومیه، خیابان امام خمینی، خیابان خیام جنوبی، پشت کلیسای آنجلیک', 'کلیسای ننه مریم ارومیه که به اسم‌های کلیسای حضرت مریم، مارت مریم و شرق‌آشور شناخته می‌شود، دومین کلیسای قدیمی جهان بعد از کلیسای بیت‌لحم در فلسطین است. قدمت این بنا به قرن اول میلادی می‌رسد و در ابتدا به‌عنوان آتشکده‌ای زرتشتی ساخته شده بود. پس از ورود مسیحیت به منطقه، این مکان به کلیسا تبدیل شد و در طول تاریخ بارها بازسازی شده است.\nآدرس: ارومیه، خیابان امام خمینی، خیابان خیام جنوبی، پشت کلیسای آنجلیک', 37.5447615, 45.0679850, '2026-07-30 20:12:02', '2026-07-30 20:21:02'),
	(43, '628b780c-84b3-4433-9b91-028595073339', 26, 'کلیسای قره باغ', 'یکی از دیدنی‌های تاریخی استان آذربایجان غربی که به دوره ایلخانی-صفوی تعلق دارد، کلیسای قره باغ است. این کلیسا شامل سه بخش اصلی محل عوام، محل سرودخوانان و محراب است و با نام کلیسای سورپ پطرس نیز شناخته می‌شود. ساختمان کلیسای قره باغ شامل تالاری مستطیل‌شکل با مساحت حدود ۱۷۰ متر مربع بود که امروزه تنها بخش اندکی از دیوار جنوبی آن باقی مانده است. در نزدیکی این کلیسا، قبرستان بزرگی با سنگ‌های لاشه‌ای و چهارگوش وجود دارد و آثار کمی از بناهای خشتی و مسکونی ارمنیان نیز هم‌چنان پابرجاست.\nآدرس: آذربایجان ', 'یکی از دیدنی‌های تاریخی استان آذربایجان غربی که به دوره ایلخانی-صفوی تعلق دارد، کلیسای قره باغ است. این کلیسا شامل سه بخش اصلی محل عوام، محل سرودخوانان و محراب است و با نام کلیسای سورپ پطرس نیز شناخته می‌شود. ساختمان کلیسای قره باغ شامل تالاری مستطیل‌شکل با مساحت حدود ۱۷۰ متر مربع بود که امروزه تنها بخش اندکی از دیوار جنوبی آن باقی مانده است. در نزدیکی این کلیسا، قبرستان بزرگی با سنگ‌های لاشه‌ای و چهارگوش وجود دارد و آثار کمی از بناهای خشتی و مسکونی ارمنیان نیز هم‌چنان پابرجاست.\nآدرس: آذربایجان غربی، ۷۵ کیلومتری شمال ‌شرق ارومیه، ۳۵ کیلومتری جنوب ‌شرق شهرستان سلماس، روستای قره باغ', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:21:10'),
	(44, '8a9d1c68-3642-4073-bfb9-cf150e3f796c', 26, 'آبشار شلماش سردشت', 'آبشار شلماش یکی از مهم‌ترین جاذبه‌های طبیعی و جاهای توریستی آذربایجان غربی در سردشت بوده که در دل یک دره سرسبز به پایین می‌ریزد. این آبشار زیبا از سه آبشار پلکانی متوالی تشکیل می‌شود که آب آن از رودخانه زاب کوچک تامین می‌گردد. وجه تسمیه آبشار شلماش به زبان کردی ‌از کلمه شل « بزرگ» و ماش به معنی «صخره عظیم» گرفته شده که وجود صخره‌های بلند در کنار آبشار را نشان می‌دهد. بهترین زمان بازدید از این آبشار اوایل خرداد تا اواسط پاییز است، یعنی زمانی که هوا معتدل و طبیعت در اوج زیبایی خود قرار دارد. اگر ق', 'آبشار شلماش یکی از مهم‌ترین جاذبه‌های طبیعی و جاهای توریستی آذربایجان غربی در سردشت بوده که در دل یک دره سرسبز به پایین می‌ریزد. این آبشار زیبا از سه آبشار پلکانی متوالی تشکیل می‌شود که آب آن از رودخانه زاب کوچک تامین می‌گردد. وجه تسمیه آبشار شلماش به زبان کردی ‌از کلمه شل « بزرگ» و ماش به معنی «صخره عظیم» گرفته شده که وجود صخره‌های بلند در کنار آبشار را نشان می‌دهد. بهترین زمان بازدید از این آبشار اوایل خرداد تا اواسط پاییز است، یعنی زمانی که هوا معتدل و طبیعت در اوج زیبایی خود قرار دارد. اگر قصد رفتن به آبشار شلماش را دارید، فراموش نکنید که درون حوضچه پایین آبشار نروید، زیرا جریان قوی آب و عمق‌های متفاوت آن ممکن است برای شما خطرساز شود.\nآدرس: سردشت، جاده سردشت شلماش، خیابان آبشار', 36.0979733, 45.4939402, '2026-07-30 20:12:02', '2026-07-30 20:21:13'),
	(45, '4432cf2a-d7ce-4545-9fd1-1f0ebc21e879', 26, 'رودخانه زاب', 'زاب یکی از طولانی‌ترین رودخانه‌های آذربایجان غربی است که از کوه‌های زاگرس سرچشمه می‌گیرد، از سردشت عبور می‌کند و در نهایت به رودخانه دجله در عراق می‌پیوندد. کنار این رود، مکانی است که ابومسلم خراسانی (سردار ایرانی)، مروان بن حمار، آخرین خلیفه اموی را شکست داد. زاب حدود ۴۰۰ کیلومتر طول دارد و برای کشاورزی و زندگی مردم منطقه اهمیت زیادی دارد. در فصل بهار، حجم آب زاب زیاد شده و زیبایی طبیعت اطراف آن دوچندان می‌شود. با اینکه زاب مقصدی جذاب برای طبیعت‌گردی است اما به دلیل عمق زیاد خود برای شنا کردن چ', 'زاب یکی از طولانی‌ترین رودخانه‌های آذربایجان غربی است که از کوه‌های زاگرس سرچشمه می‌گیرد، از سردشت عبور می‌کند و در نهایت به رودخانه دجله در عراق می‌پیوندد. کنار این رود، مکانی است که ابومسلم خراسانی (سردار ایرانی)، مروان بن حمار، آخرین خلیفه اموی را شکست داد. زاب حدود ۴۰۰ کیلومتر طول دارد و برای کشاورزی و زندگی مردم منطقه اهمیت زیادی دارد. در فصل بهار، حجم آب زاب زیاد شده و زیبایی طبیعت اطراف آن دوچندان می‌شود. با اینکه زاب مقصدی جذاب برای طبیعت‌گردی است اما به دلیل عمق زیاد خود برای شنا کردن چندان مناسب نیست.\nآدرس: سردشت، جاده پیرانشهر سردشت', 36.3062623, 45.4174817, '2026-07-30 20:12:02', '2026-07-30 20:21:15'),
	(46, 'e61c36ed-bf94-491c-96c5-dd2aa3659a79', 26, 'منطقه آلان', 'منطقه آلان در شهرستان سردشت، یکی از جاذبه‌های کمتر شناخته‌شده اما بسیار جذاب برای علاقه‌مندان به طبیعت و ماجراجویی است. این منطقه با رودخانه‌ای پرآب و خروشان به نام آلان‌چای، طبیعتی بکر و کوهستانی داشته و در فصل‌های بهار و تابستان بسیار دیدنی است. از جاذبه‌های طبیعی این منطقه می‌توان به مجموعه آبشارهای شش‌گانه رزگه اشاره کرد که در فصل‌های بهار و تابستان، خوش‌آب‌وهوا و زیبا می‌شوند. علاوه بر جذابیت‌های طبیعی، این منطقه از نظر تولید محصولات ارگانیک مانند انار و انجیر معروف است.\nآدرس: ۱۳ کیلومتری ج', 'منطقه آلان در شهرستان سردشت، یکی از جاذبه‌های کمتر شناخته‌شده اما بسیار جذاب برای علاقه‌مندان به طبیعت و ماجراجویی است. این منطقه با رودخانه‌ای پرآب و خروشان به نام آلان‌چای، طبیعتی بکر و کوهستانی داشته و در فصل‌های بهار و تابستان بسیار دیدنی است. از جاذبه‌های طبیعی این منطقه می‌توان به مجموعه آبشارهای شش‌گانه رزگه اشاره کرد که در فصل‌های بهار و تابستان، خوش‌آب‌وهوا و زیبا می‌شوند. علاوه بر جذابیت‌های طبیعی، این منطقه از نظر تولید محصولات ارگانیک مانند انار و انجیر معروف است.\nآدرس: ۱۳ کیلومتری جنوب سردشت، حاشیه جاده ارتباطی سردشت به رزگه', 17.4819787, 44.0972972, '2026-07-30 20:12:02', '2026-07-30 20:21:19'),
	(47, '05342513-be21-4539-bd6d-01a29c18d89e', 26, 'آبشار رزگه', 'آبشار رزگه، نگینی دیگر در دل طبیعت سرسبز سردشت است که از صخره‌های بلند و عمودی سرازیر می‌شود. بهترین زمان برای بازدید از این آبشار، فصل بهار است؛ زمانی که با ذوب شدن برف‌ها و بارش‌های بهاری، حجم آب آبشار به حد زیادی می‌رسد و طبیعت اطراف را در هاله‌ای از قطرات ریز خود می‌پوشاند. در زمستان با سرد شدن هوا، آبشار رزگه شکل خاصی پیدا می‌کند و به قندیل یخی بزرگی تبدیل می‌شود.\nآدرس: شهر سردشت، خیابان آذربایجان غربی', 'آبشار رزگه، نگینی دیگر در دل طبیعت سرسبز سردشت است که از صخره‌های بلند و عمودی سرازیر می‌شود. بهترین زمان برای بازدید از این آبشار، فصل بهار است؛ زمانی که با ذوب شدن برف‌ها و بارش‌های بهاری، حجم آب آبشار به حد زیادی می‌رسد و طبیعت اطراف را در هاله‌ای از قطرات ریز خود می‌پوشاند. در زمستان با سرد شدن هوا، آبشار رزگه شکل خاصی پیدا می‌کند و به قندیل یخی بزرگی تبدیل می‌شود.\nآدرس: شهر سردشت، خیابان آذربایجان غربی', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:21:27'),
	(48, 'a6859fa2-74e2-4a18-9d88-80b118993414', 26, 'پل قلعه تاسیان یا پل قلاتاسیان', 'پل تاریخی قلعه تاسیان که با نام قلاتاسیان نیز شناخته می‌شود، شاهکار معماری بازمانده از دوره قاجار است که روی رودخانه زاب کوچک قرار دارد. پل قلعه تاسیان با ساختاری مقاوم و پنج پایه از مصالح سنتی مانند سنگ‌های طبیعی و ملات ساروج ساخته شده است. تاریخچه ساخت پل قلعه تاسیان احتمالا به دوران پیش از اسلام بازمی‌گردد. طبق نظرات باستان‌شناسان این پل در اواسط قرن سیزدهم هجری به دستور شیخ مولانا ساخته شده، به همین خاطر به «پل مولانا» نیز شهرت دارد.\nآدرس: مسیر جاده پیرانشهر به سردشت، بخش وزینه', 'پل تاریخی قلعه تاسیان که با نام قلاتاسیان نیز شناخته می‌شود، شاهکار معماری بازمانده از دوره قاجار است که روی رودخانه زاب کوچک قرار دارد. پل قلعه تاسیان با ساختاری مقاوم و پنج پایه از مصالح سنتی مانند سنگ‌های طبیعی و ملات ساروج ساخته شده است. تاریخچه ساخت پل قلعه تاسیان احتمالا به دوران پیش از اسلام بازمی‌گردد. طبق نظرات باستان‌شناسان این پل در اواسط قرن سیزدهم هجری به دستور شیخ مولانا ساخته شده، به همین خاطر به «پل مولانا» نیز شهرت دارد.\nآدرس: مسیر جاده پیرانشهر به سردشت، بخش وزینه', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:21:35'),
	(49, '5f049c8e-175d-4985-a277-3c27827fb5f3', 26, 'حمام تاریخی سردشت', 'گرمابه تاریخی بیستون یکی از ارزشمندترین آثار تاریخی سردشت به شمار می‌رود. برای دسترسی به این حمام باید حدود ۱۱ کیلومتر از آبشار شلماش فاصله بگیرید. حمام سردشت با مساحتی در حدود ۳۰۰ مترمربع، مربوط به دوره قاجار بوده و تا همین چند سال پیش به‌صورت عمومی استفاده می‌شد. بر اساس گفته اهالی، سازنده اصلی این بنا خواهر سردار عزیز خان، فرمانده کل قشون ایران در زمان ناصرالدین شاه بود. حمام بیستون تمام فضاهای یک حمام سنتی ایرانی را در خود جای داده است.\nآدرس: سردشت، میدان صلاح الدین ایوبی، خیابان امام خمینی', 'گرمابه تاریخی بیستون یکی از ارزشمندترین آثار تاریخی سردشت به شمار می‌رود. برای دسترسی به این حمام باید حدود ۱۱ کیلومتر از آبشار شلماش فاصله بگیرید. حمام سردشت با مساحتی در حدود ۳۰۰ مترمربع، مربوط به دوره قاجار بوده و تا همین چند سال پیش به‌صورت عمومی استفاده می‌شد. بر اساس گفته اهالی، سازنده اصلی این بنا خواهر سردار عزیز خان، فرمانده کل قشون ایران در زمان ناصرالدین شاه بود. حمام بیستون تمام فضاهای یک حمام سنتی ایرانی را در خود جای داده است.\nآدرس: سردشت، میدان صلاح الدین ایوبی، خیابان امام خمینی', 36.1559032, 45.4791159, '2026-07-30 20:12:02', '2026-07-30 20:21:37'),
	(50, '3fa27f37-2da5-47ff-b164-2bb3fc1bf5a0', 26, 'چشمه کانی گراوان سردشت', 'چشمه کانی گراوان یکی از جاذبه‌های طبیعی استان آذربایجان غربی است که در اطراف آن جنگل‌های بلوط و آبشارهای زیادی وجود دارد. آب چشمه گراوان املاح معدنی زیادی داشته که برای درمان بیماری‌های پوستی، دردهای عضلانی و رماتیسم مفید هستند. این چشمه در میان سازه‌های آهکی طبیعی جریان دارد و آب آن همواره جوشان و سرد است، به همین دلیل قابل شرب نیست. نام کانی گراوان کردی است؛ «کانی» به معنی چشمه و «گراوان» به معنای سنگین است که به املاح آب اشاره دارد.\nآدرس: شهرستان ربط، جاده ربط به مهاباد، جاده مخصوص گراوان', 'چشمه کانی گراوان یکی از جاذبه‌های طبیعی استان آذربایجان غربی است که در اطراف آن جنگل‌های بلوط و آبشارهای زیادی وجود دارد. آب چشمه گراوان املاح معدنی زیادی داشته که برای درمان بیماری‌های پوستی، دردهای عضلانی و رماتیسم مفید هستند. این چشمه در میان سازه‌های آهکی طبیعی جریان دارد و آب آن همواره جوشان و سرد است، به همین دلیل قابل شرب نیست. نام کانی گراوان کردی است؛ «کانی» به معنی چشمه و «گراوان» به معنای سنگین است که به املاح آب اشاره دارد.\nآدرس: شهرستان ربط، جاده ربط به مهاباد، جاده مخصوص گراوان', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:21:45'),
	(51, 'b4527b54-449b-41b9-8a7a-49a837c59009', 26, 'دریاچه تخت سلیمان تکاب', 'میان کوهستان‌های سرسبز تکاب، دریاچه تخت سلیمان با آب زلال و فیروزه‌ای‌رنگ قرار گرفته که قدمتی ۳ هزار ساله دارد. عمق این دریاچه بیش از ۱۱۲ متر بوده و لایه‌های رسوبی و ساختارهای آهکی کف آن، توجه بازدیدکنندگان را جلب می‌کند. بر اساس افسانه‌ها، دریاچه تخت سلیمان گنج‌هایی مانند جام مقدس، گنج کوروش و انگشتر حضرت سلیمان را در دل خود جای داده است.\nآدرس: شهرستان تکاب، بخش تخت سلیمان، ۳ کیلومتری شرق روستای نصرت‌آباد', 'میان کوهستان‌های سرسبز تکاب، دریاچه تخت سلیمان با آب زلال و فیروزه‌ای‌رنگ قرار گرفته که قدمتی ۳ هزار ساله دارد. عمق این دریاچه بیش از ۱۱۲ متر بوده و لایه‌های رسوبی و ساختارهای آهکی کف آن، توجه بازدیدکنندگان را جلب می‌کند. بر اساس افسانه‌ها، دریاچه تخت سلیمان گنج‌هایی مانند جام مقدس، گنج کوروش و انگشتر حضرت سلیمان را در دل خود جای داده است.\nآدرس: شهرستان تکاب، بخش تخت سلیمان، ۳ کیلومتری شرق روستای نصرت‌آباد', 36.5198682, 47.1357694, '2026-07-30 20:12:02', '2026-07-30 20:21:48'),
	(52, '41fcdbc5-9d6d-4e3b-a2b9-9fb7fe8df89b', 26, 'چمن متحرک چملی تکاب', 'چمن متحرک یا چملی گُل یکی از عجیب‌ترین پدیده‌های طبیعی ایران و حتی جهان است. این برکه کوچک از ریشه‌های به هم تنیده نی‌ها تشکیل شده که بدون هیچ اتصالی به زمین، روی آب شناور مانده‌اند. این چمنزار شناور با وزش باد یا جریان هوا، به آرامی در جهات مختلف حرکت کرده و همین ویژگی، چملی گُل را به رازی سر به مهر و جاذبه‌ای خاص تبدیل می‌کند. در این منطقه، درختان بید و چنار زیادی وجود دارد و همین درختان باعث شده‌اند تا چملی تکاب حتی در فصل زمستان نیز سبزی خود را حفظ کند. دلیل علمی حرکت این جزیره کاملاً مشخص ن', 'چمن متحرک یا چملی گُل یکی از عجیب‌ترین پدیده‌های طبیعی ایران و حتی جهان است. این برکه کوچک از ریشه‌های به هم تنیده نی‌ها تشکیل شده که بدون هیچ اتصالی به زمین، روی آب شناور مانده‌اند. این چمنزار شناور با وزش باد یا جریان هوا، به آرامی در جهات مختلف حرکت کرده و همین ویژگی، چملی گُل را به رازی سر به مهر و جاذبه‌ای خاص تبدیل می‌کند. در این منطقه، درختان بید و چنار زیادی وجود دارد و همین درختان باعث شده‌اند تا چملی تکاب حتی در فصل زمستان نیز سبزی خود را حفظ کند. دلیل علمی حرکت این جزیره کاملاً مشخص نیست و برخی آن را مرتبط با حرکت وضعی زمین می‌دانند. وجود مرغابی‌ها و ماهی‌های وحشی در اطراف این برکه، جلوه‌ای خاص به آن بخشیده است.\nآدرس: شهرستان تکاب، جاده قزل قشلاق، جاده برنجه', 36.4766807, 47.2253348, '2026-07-30 20:12:02', '2026-07-30 20:21:50'),
	(53, '5dbf7719-93a6-42fd-8f2a-cd69bb7842a3', 26, 'تخت سلیمان تکاب', 'در دل کوهستان‌های تکاب، تخت سلیمان یکی از باشکوه‌ترین میراث‌های باستانی ایران است. این مجموعه با بیش از ۳ هزار سال قدمت، مرکز مذهبی، سیاسی و اجتماعی دوران مادها، هخامنشیان و اشکانیان بوده و در دوره ساسانیان به اوج شکوه خود رسیده است. آتشکده آذرگشسب و ایوان خسرو از مهم‌ترین آثار تخت سلیمان هستند. امروزه تخت سلیمان در فهرست میراث جهانی یونسکو ثبت شده و هم‌چنان ارزش تاریخی خود را حفظ کرده است. طی کاوش‌های باستان‌شناسی، بقایای معابدی مانند آذرگشسب، آناهیتا و ایوان خسرو پرویز در این مجموعه پیدا شدند.', 'در دل کوهستان‌های تکاب، تخت سلیمان یکی از باشکوه‌ترین میراث‌های باستانی ایران است. این مجموعه با بیش از ۳ هزار سال قدمت، مرکز مذهبی، سیاسی و اجتماعی دوران مادها، هخامنشیان و اشکانیان بوده و در دوره ساسانیان به اوج شکوه خود رسیده است. آتشکده آذرگشسب و ایوان خسرو از مهم‌ترین آثار تخت سلیمان هستند. امروزه تخت سلیمان در فهرست میراث جهانی یونسکو ثبت شده و هم‌چنان ارزش تاریخی خود را حفظ کرده است. طی کاوش‌های باستان‌شناسی، بقایای معابدی مانند آذرگشسب، آناهیتا و ایوان خسرو پرویز در این مجموعه پیدا شدند.\nآدرس: شهرستان تکاب، بخش تخت سلیمان، سه کیلومتری شرق روستای نصرت‌آباد', 36.6098675, 47.2172077, '2026-07-30 20:12:02', '2026-07-30 20:21:52'),
	(54, '120933a2-f350-4582-b3c3-7d0ea942b8c1', 26, 'زندان سلیمان', 'اگر نمی‌دانید که مخوف‌ترین زندان‌ دنیا در کجا قرار دارد، باید بگوییم که یکی از ترسناک‌ترین زندان‌های جهان، در مجموعه تخت سلیمان جای گرفته است. زندان سلیمان (یا زندان دیو)، نه یک زندان برای انسان‌ها، بلکه طبق افسانه‌های محلی، محل حبس دیوهای سرکشی بوده که از فرمان حضرت سلیمان نافرمانی کرده بودند. دیوارهای زندان سلیمان آن‌قدر بلند هستند که هیچ دیوی با آن جثه نمی‌توانست از آن فرار کند.\nآدرس: شهرستان تکاب، جاده تخت سلیمان دندی، جاده تکاب تخت سلیمان', 'اگر نمی‌دانید که مخوف‌ترین زندان‌ دنیا در کجا قرار دارد، باید بگوییم که یکی از ترسناک‌ترین زندان‌های جهان، در مجموعه تخت سلیمان جای گرفته است. زندان سلیمان (یا زندان دیو)، نه یک زندان برای انسان‌ها، بلکه طبق افسانه‌های محلی، محل حبس دیوهای سرکشی بوده که از فرمان حضرت سلیمان نافرمانی کرده بودند. دیوارهای زندان سلیمان آن‌قدر بلند هستند که هیچ دیوی با آن جثه نمی‌توانست از آن فرار کند.\nآدرس: شهرستان تکاب، جاده تخت سلیمان دندی، جاده تکاب تخت سلیمان', 36.6149010, 47.2015190, '2026-07-30 20:12:02', '2026-07-30 20:21:55'),
	(55, '96bd97bb-635c-4023-a446-531be0cc994a', 26, 'آتشکده آذرگشسب تکاب', 'آماده شوید تا دوباره به قلب قلعه تاریخی تخت سلیمان سفر کنیم؛ جایی به نام آتشکده آذرگشسب! این آتشکده، بنایی فراتر از یک سازه باستانی است که نامش در شاهنامه و اوستا آمده است. نام اسرارآمیز این آتشکده، آذرگشسب به معنای آتش اسب نر است و ریشه در افسانه‌ها دارد. گفته شده که کیخسرو (پادشاه ایرانی) در تاریکی دیوان، ناگهان شاهد فرود آمدن آتشی بر یال اسب خود شد که جهان را روشن کرد و به خاطر این اتفاق، آتشکده‌ای در این مکان ساخت.\nآدرس: آذربایجان غربی، ۴۵ کیلومتری شمال شرقی تکاب، روستای نصرت‌آباد، روستای تخ', 'آماده شوید تا دوباره به قلب قلعه تاریخی تخت سلیمان سفر کنیم؛ جایی به نام آتشکده آذرگشسب! این آتشکده، بنایی فراتر از یک سازه باستانی است که نامش در شاهنامه و اوستا آمده است. نام اسرارآمیز این آتشکده، آذرگشسب به معنای آتش اسب نر است و ریشه در افسانه‌ها دارد. گفته شده که کیخسرو (پادشاه ایرانی) در تاریکی دیوان، ناگهان شاهد فرود آمدن آتشی بر یال اسب خود شد که جهان را روشن کرد و به خاطر این اتفاق، آتشکده‌ای در این مکان ساخت.\nآدرس: آذربایجان غربی، ۴۵ کیلومتری شمال شرقی تکاب، روستای نصرت‌آباد، روستای تخت سلیمان', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:22:03'),
	(56, '596fd40b-82f2-4702-bce5-7dc8e9f2515e', 26, 'آبشار خرپاپ پیرانشهر', 'آبشار خرپاپ یکی از زیباترین جاذبه‌های طبیعی پیرانشهر و جاهای دیدنی و گردشگری آذربایجان غربی در دل جنگل‌های سرسبز است. نام «خرپاپ» از واژه‌ کردی به نام «جای زیبا و پر آب» گرفته شده و کاملا با ویژگی‌های این آبشار همخوانی دارد. آبشار خرپاپ با ارتفاع تقریبی ۱۵ متر، در فصل بهار به دلیل ذوب برف‌ کوه‌ها و بارش‌های بهاری بسیار پرآب‌ است. برای رسیدن به آبشار خرپاپ باید از مسیر جاده پیرانشهر به سردشت حرکت کنید و پس از حدود ۲۵ کیلومتر وارد جاده روستای گزگسک شوید.\nآدرس: آذربایجان غربی، ۲۲ کیلومتری جنوب پیرا', 'آبشار خرپاپ یکی از زیباترین جاذبه‌های طبیعی پیرانشهر و جاهای دیدنی و گردشگری آذربایجان غربی در دل جنگل‌های سرسبز است. نام «خرپاپ» از واژه‌ کردی به نام «جای زیبا و پر آب» گرفته شده و کاملا با ویژگی‌های این آبشار همخوانی دارد. آبشار خرپاپ با ارتفاع تقریبی ۱۵ متر، در فصل بهار به دلیل ذوب برف‌ کوه‌ها و بارش‌های بهاری بسیار پرآب‌ است. برای رسیدن به آبشار خرپاپ باید از مسیر جاده پیرانشهر به سردشت حرکت کنید و پس از حدود ۲۵ کیلومتر وارد جاده روستای گزگسک شوید.\nآدرس: آذربایجان غربی، ۲۲ کیلومتری جنوب پیرانشهر، جنگل‌های پردانان', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:22:10'),
	(57, 'ba309cd5-8af9-4d13-8fd5-e6ec34617dbe', 26, 'روستای خورنج', 'در روستای خورنج می‌توانید سنگ‌های غول‌پیکری را ببینید که به شکل نوارهای سنگی هستند. در اطراف این روستا بقایای یک دژ کوهستانی و کتیبه‌های قدیمی وجود دارد که از تاریخ کهن و پرفراز و نشیب این منطقه حکایت می‌کند. نکته جالب در مورد خورنج این است که هر یک از این سنگ‌ها، نام و داستان محلی خاص خود را دارند و برخی از آن‌ها دارای نقش‌برجسته‌ از حیواناتی مانند شتر، مار و پرنده هستند. جالب‌ترین بخش این منطقه، حفره‌ای غارمانند به نام «کونه پیست» است که در تمام فصل‌ها، حتی در وسط تابستان، باد سرد و شدیدی از آ', 'در روستای خورنج می‌توانید سنگ‌های غول‌پیکری را ببینید که به شکل نوارهای سنگی هستند. در اطراف این روستا بقایای یک دژ کوهستانی و کتیبه‌های قدیمی وجود دارد که از تاریخ کهن و پرفراز و نشیب این منطقه حکایت می‌کند. نکته جالب در مورد خورنج این است که هر یک از این سنگ‌ها، نام و داستان محلی خاص خود را دارند و برخی از آن‌ها دارای نقش‌برجسته‌ از حیواناتی مانند شتر، مار و پرنده هستند. جالب‌ترین بخش این منطقه، حفره‌ای غارمانند به نام «کونه پیست» است که در تمام فصل‌ها، حتی در وسط تابستان، باد سرد و شدیدی از آن می‌وزد، به حدی که مردم از آن به عنوان یک یخچال طبیعی استفاده می‌کردند.\nآدرس: آذربایجان غربی، ۲۰ کیلومتری شمال شرقی پیرانشهر، مسیر جاده‌ پیرانشهر به مهاباد', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:22:18'),
	(58, '769df9ad-6ec1-4207-a63c-7240e9c557be', 26, 'سد جلدیان', 'در دامنه‌های سرسبز شهرستان پیرانشهر، سد خاکی جلدیان قرار گرفته که ارتفاعی بیش از ۲۴ متر و حجمی حدود ۲۰۳ میلیون مترمکعب دارد. در اطراف این سد می‌توانید پیاده‌روی کنید، به تماشای غروب خورشید بنشینید و عکس‌هایی فراموش‌نشدنی از خودتان و مناظر این منطقه بگیرید. هم‌چنین اگر اهل ماهیگیری هستید، می‌توانید در کنار این سد، شانس خود را برای گرفتن ماهی امتحان کنید!\nآدرس: آذربایجان غربی، شهرستان پیرانشهر، حدود ۲۵ کیلومتر شمال غربی پیرانشهر، روستای جلدیان', 'در دامنه‌های سرسبز شهرستان پیرانشهر، سد خاکی جلدیان قرار گرفته که ارتفاعی بیش از ۲۴ متر و حجمی حدود ۲۰۳ میلیون مترمکعب دارد. در اطراف این سد می‌توانید پیاده‌روی کنید، به تماشای غروب خورشید بنشینید و عکس‌هایی فراموش‌نشدنی از خودتان و مناظر این منطقه بگیرید. هم‌چنین اگر اهل ماهیگیری هستید، می‌توانید در کنار این سد، شانس خود را برای گرفتن ماهی امتحان کنید!\nآدرس: آذربایجان غربی، شهرستان پیرانشهر، حدود ۲۵ کیلومتر شمال غربی پیرانشهر، روستای جلدیان', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:22:26'),
	(59, 'a3b7916e-c25c-4e10-8762-4a8df3428fc7', 26, 'منطقه جنگلی میرآباد', 'یکی از بهترین مکان های دیدنی آذربایجان غربی، روستای میرآباد است که در دل طبیعتی سرسبز و کنار رودخانه‌ زیبای گادر واقع شده است. مناظر جنگلی این منطقه با درختان بلوط، زالزالک و گلابی وحشی، بهترین فرصت برای طبیعت‌گردی، عکاسی و گذراندن روزی آرام در دل کوهستان است. اگر به دنبال تجدید انرژی و رفع خستگی از زندگی شهری هستید، میرآباد گزینه‌ای عالی برای شما خواهد بود. در منطقه میرآباد، جانورانی مانند خرس قهوه‌ای، سنجاب ایرانی و… زندگی می‌کنند و محل رویش گیاهان متنوعی است.\nآدرس: آذربایجان‌غربی، ۲۳ کیلومتری', 'یکی از بهترین مکان های دیدنی آذربایجان غربی، روستای میرآباد است که در دل طبیعتی سرسبز و کنار رودخانه‌ زیبای گادر واقع شده است. مناظر جنگلی این منطقه با درختان بلوط، زالزالک و گلابی وحشی، بهترین فرصت برای طبیعت‌گردی، عکاسی و گذراندن روزی آرام در دل کوهستان است. اگر به دنبال تجدید انرژی و رفع خستگی از زندگی شهری هستید، میرآباد گزینه‌ای عالی برای شما خواهد بود. در منطقه میرآباد، جانورانی مانند خرس قهوه‌ای، سنجاب ایرانی و… زندگی می‌کنند و محل رویش گیاهان متنوعی است.\nآدرس: آذربایجان‌غربی، ۲۳ کیلومتری سردشت و ۲۵ کیلومتری پیرانشهر، منطقه میرآباد', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:22:35'),
	(60, '4832ef02-7f06-4c19-b032-9b11c09154c7', 26, 'جنگل‌های پردانان', 'برای رسیدن به جنگل‌های پردانان یکی دیگر از جاهای دیدنی آذربایجان غربی، کافی است جاده پرپیچ‌وخم پیرانشهر به سردشت را دنبال کنید. این مسیر در بهار پر از شکوفه‌ شده و عطر گیاهانش هوش از سر می‌برد. در عمق این جنگل زیبا، آبشار خرپاپ قرار دارد که در قسمت‌های قبل به آن اشاره کردیم. جنگل‌های پردانان در دل پیرانشهر، تکه‌ای از بهشت منطقه زاگرس هستند؛ جایی که کوه، چشمه، رودخانه و درختان بلوط در کنار هم قرار گرفته‌اند.\nآدرس: ۳۵ کیلومتری پیرانشهر به طرف سردشت، نرسیده به روستای شیوه مردان', 'برای رسیدن به جنگل‌های پردانان یکی دیگر از جاهای دیدنی آذربایجان غربی، کافی است جاده پرپیچ‌وخم پیرانشهر به سردشت را دنبال کنید. این مسیر در بهار پر از شکوفه‌ شده و عطر گیاهانش هوش از سر می‌برد. در عمق این جنگل زیبا، آبشار خرپاپ قرار دارد که در قسمت‌های قبل به آن اشاره کردیم. جنگل‌های پردانان در دل پیرانشهر، تکه‌ای از بهشت منطقه زاگرس هستند؛ جایی که کوه، چشمه، رودخانه و درختان بلوط در کنار هم قرار گرفته‌اند.\nآدرس: ۳۵ کیلومتری پیرانشهر به طرف سردشت، نرسیده به روستای شیوه مردان', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:22:43'),
	(61, '483035ab-74e3-4258-a4a4-9c7fa8987c80', 26, 'کوهستان‌های قندیل سد جلدیان', 'مورد بعدی در لیست مکان های دیدنی استان آذربایجان غربی به کوهستان‌های قندیل در مرز ایران، عراق و ترکیه تعلق دارد؛ جایی که قله‌های آن در دل مه و ابر پنهان می‌شوند. مردم محلی به تمام این منطقه «کوهستان قندیل» می‌گویند که بلندترین قله آن، که و کز (Kavkez) در مرز ایران و ترکیه قرار دارد. طبیعت بکر با دیواره‌های سنگی عظیم، این منطقه را به مقصدی عالی برای کوهنوردان و عاشقان طبیعت تبدیل کرده است.\nآدرس: آذربایجان غربی، شهرستان پیرانشهر، منطقه مرزی ایران و عراق', 'مورد بعدی در لیست مکان های دیدنی استان آذربایجان غربی به کوهستان‌های قندیل در مرز ایران، عراق و ترکیه تعلق دارد؛ جایی که قله‌های آن در دل مه و ابر پنهان می‌شوند. مردم محلی به تمام این منطقه «کوهستان قندیل» می‌گویند که بلندترین قله آن، که و کز (Kavkez) در مرز ایران و ترکیه قرار دارد. طبیعت بکر با دیواره‌های سنگی عظیم، این منطقه را به مقصدی عالی برای کوهنوردان و عاشقان طبیعت تبدیل کرده است.\nآدرس: آذربایجان غربی، شهرستان پیرانشهر، منطقه مرزی ایران و عراق', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:22:51'),
	(62, '0c6d8127-779b-4279-8cdc-9951a0d54028', 26, 'بازارچه مرزی تمرچین', 'بازارچه مرزی تمرچین پیرانشهر در نزدیکی مرز ایران و عراق قرار گرفته و به دلیل نزدیکی به خاک عراق، کالاهای وارداتی متنوع و باکیفیتی را با قیمت‌هایی بسیار مناسب عرضه می‌کند. بسیاری از افراد تمرچین را به نام «بازار مرکزی بزرگ پیرانشهر» می‌شناسند. در این بازار می‌توانید انواع پوشاک زنانه و مردانه، کیف و کفش، لوازم خانگی، وسایل برقی، لوازم دیجیتال و حتی خوراکی‌های خاص وارداتی را با قیمت‌هایی کمتر از سایر نقاط کشور بخرید. بازارچه مرزی تمرچین در سال ۱۳۸۵ عنوان «پُررونق‌ترین بازار مرزی کشور» را از آن خود', 'بازارچه مرزی تمرچین پیرانشهر در نزدیکی مرز ایران و عراق قرار گرفته و به دلیل نزدیکی به خاک عراق، کالاهای وارداتی متنوع و باکیفیتی را با قیمت‌هایی بسیار مناسب عرضه می‌کند. بسیاری از افراد تمرچین را به نام «بازار مرکزی بزرگ پیرانشهر» می‌شناسند. در این بازار می‌توانید انواع پوشاک زنانه و مردانه، کیف و کفش، لوازم خانگی، وسایل برقی، لوازم دیجیتال و حتی خوراکی‌های خاص وارداتی را با قیمت‌هایی کمتر از سایر نقاط کشور بخرید. بازارچه مرزی تمرچین در سال ۱۳۸۵ عنوان «پُررونق‌ترین بازار مرزی کشور» را از آن خود کرد و امروز هم نقش مهمی در اقتصاد پیرانشهر دارد.\nآدرس: آذربایجان غربی، کیلومتر ۱۱ جاده گمرک پیرانشهر', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:22:59'),
	(63, '1e78010f-1df0-4a58-b654-0b9bc9da2369', 26, 'تالاب یوسفکند مهاباد', 'تالاب یوسفکند در مهاباد که به زبان محلی به آن «حسن خان» هم می‌گویند، یکی از تالاب‌های مهم بوده که در طول سال میزبان انواع پرندگان بومی و مهاجر است. در هر فصل حتی زمستان، گونه‌های مختلفی از فلامینگو، حواصیل و عقاب تالابی در این تالاب دیده می‌شوند. تالاب یوسفکند، یکی از بهترین مکان های دیدنی آذربایجان غربی برای تماشای پرندگان است.\nآدرس: ۵ کیلومتری شهر مهاباد، نرسیده به روستای یوسفکند', 'تالاب یوسفکند در مهاباد که به زبان محلی به آن «حسن خان» هم می‌گویند، یکی از تالاب‌های مهم بوده که در طول سال میزبان انواع پرندگان بومی و مهاجر است. در هر فصل حتی زمستان، گونه‌های مختلفی از فلامینگو، حواصیل و عقاب تالابی در این تالاب دیده می‌شوند. تالاب یوسفکند، یکی از بهترین مکان های دیدنی آذربایجان غربی برای تماشای پرندگان است.\nآدرس: ۵ کیلومتری شهر مهاباد، نرسیده به روستای یوسفکند', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:23:08'),
	(64, 'fbe64904-f6a8-41e7-ac8a-d7de972900c0', 26, 'غار آبی سهولان مهاباد', 'غار سهولان، دومین غار آبی بزرگ ایران است که در لیست جاهای زیبای آذربایجان غربی جای می‌گیرد. این غار که در زبان کردی به معنی «یخبندان» است، به دلیل سرمای مطبوع خود یکی از بهترین مقصدهای تابستانی است. غار سهولان از دو بخش خشک و آبی تشکیل شده است. بخش خشک این غار دارای راهروها و تالارهای بزرگ است و در بخش آبی آن، دریاچه قرار دارد. برای ورود به بخش آبی غار، بازدیدکنندگان می‌توانند سوار بر قایق‌های کوچکی شوند. در کنار دریاچه غار سهولان، فقط کبوترهای وحشی و خفاش‌ زندگی می‌کنند و به دلیل تاریکی، هیچ نو', 'غار سهولان، دومین غار آبی بزرگ ایران است که در لیست جاهای زیبای آذربایجان غربی جای می‌گیرد. این غار که در زبان کردی به معنی «یخبندان» است، به دلیل سرمای مطبوع خود یکی از بهترین مقصدهای تابستانی است. غار سهولان از دو بخش خشک و آبی تشکیل شده است. بخش خشک این غار دارای راهروها و تالارهای بزرگ است و در بخش آبی آن، دریاچه قرار دارد. برای ورود به بخش آبی غار، بازدیدکنندگان می‌توانند سوار بر قایق‌های کوچکی شوند. در کنار دریاچه غار سهولان، فقط کبوترهای وحشی و خفاش‌ زندگی می‌کنند و به دلیل تاریکی، هیچ نوع جلبکی در آب رشد نمی‌کند. غار سهولان با نام دیگر «کونه‌کوتر» نیز شناخته می‌شود که در زبان کردی به معنای «لانه کبوتر» است. مردم محلی بخش آبی غار را «کونه‌کوتر» و بخش خشکی آن را «کونه‌مالان» می‌نامند که معنی «پناهگاه» می‌دهد.\nآدرس: مهاباد، جاده بوکان مهاباد، جاده غار سهولان\nساعت بازدید: فصل بهار و تابستان از ۸:۳۰ صبح تا ۱۸، فصل پاییز و زمستان از ۸:۳۰ صبح تا ۱۷\nقیمت بلیط: 100 هزار تومان', 36.6546861, 45.9529347, '2026-07-30 20:12:02', '2026-07-30 20:23:10'),
	(65, 'b71f9c52-a8d7-47bd-8756-2076ad62cf1d', 26, 'پارک ملت مهاباد', 'پارک ملت مهاباد که با نام باغ میکائیل شناخته می‌شود، یکی از جذاب‌ترین مناطق گردشگری مهاباد در استان آذربایجان غربی است. این باغ به خاندان میکائیلی تعلق داشته و نام آن نیز از همین خاندان گرفته شده است. باغ مهاباد در نزدیکی دریاچه سد مهاباد قرار گرفته و رودخانه مهاباد از میان آن می‌گذرد. از امکانات رفاهی این پارک می‌توان به بوفه، سرویس بهداشتی، سکوهای نماز، محوطه بازی کودکان، پارکینگ و آلاچیق اشاره کرد. در فصل‌های گرم سال، بسیاری از خانواده‌ها برای پیک‌نیک و گردش به باغ مهاباد می‌آیند.\nآدرس: آذربا', 'پارک ملت مهاباد که با نام باغ میکائیل شناخته می‌شود، یکی از جذاب‌ترین مناطق گردشگری مهاباد در استان آذربایجان غربی است. این باغ به خاندان میکائیلی تعلق داشته و نام آن نیز از همین خاندان گرفته شده است. باغ مهاباد در نزدیکی دریاچه سد مهاباد قرار گرفته و رودخانه مهاباد از میان آن می‌گذرد. از امکانات رفاهی این پارک می‌توان به بوفه، سرویس بهداشتی، سکوهای نماز، محوطه بازی کودکان، پارکینگ و آلاچیق اشاره کرد. در فصل‌های گرم سال، بسیاری از خانواده‌ها برای پیک‌نیک و گردش به باغ مهاباد می‌آیند.\nآدرس: آذربایجان غربی، جاده مهاباد-پیرانشهر، کنار دریاچه سد مهاباد', 36.7703633, 45.7137465, '2026-07-30 20:12:02', '2026-07-30 20:23:13'),
	(66, '44798af1-86b5-4f37-a6a3-2cec84c4616c', 26, 'دریاچه سد مهاباد', 'یکی دیگر از جاهای دیدنی آذربایجان غربی، دریاچه سد مهاباد است که تنها چند دقیقه با مرکز شهر مهاباد فاصله دارد. این سد با بیشتر از ۵۰ سال قدمت، به‌ عنوان تنها سد جهان معروف شده که در محدوده شهری قرار دارد. سد مهاباد روی رودخانه مهاباد ساخته شده و علاوه بر تولید برق و کنترل سیلاب، مکانی مناسب برای شنا، ماهیگیری و کمپینگ است. برای استراحت و غذاخوردن می‌توانید به دکه‌های فروش غذا و چند کافه رستوران در اطراف این سد بروید.\nآدرس: مهاباد، بلوار آوراز', 'یکی دیگر از جاهای دیدنی آذربایجان غربی، دریاچه سد مهاباد است که تنها چند دقیقه با مرکز شهر مهاباد فاصله دارد. این سد با بیشتر از ۵۰ سال قدمت، به‌ عنوان تنها سد جهان معروف شده که در محدوده شهری قرار دارد. سد مهاباد روی رودخانه مهاباد ساخته شده و علاوه بر تولید برق و کنترل سیلاب، مکانی مناسب برای شنا، ماهیگیری و کمپینگ است. برای استراحت و غذاخوردن می‌توانید به دکه‌های فروش غذا و چند کافه رستوران در اطراف این سد بروید.\nآدرس: مهاباد، بلوار آوراز', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:23:21'),
	(67, '5f36d687-2062-484a-a0df-a0635f238c94', 26, 'مسجد جامع سرخ مهاباد', 'مسجد جامع مهاباد یکی از آثار تاریخی و مذهبی مهم شهر مهاباد در دوران صفویه است که به دستور حاکم وقت، بداق سلطان ساخته شد و قدمت آن به حدود ۳۵۵ سال پیش بازمی‌گردد. مردم محلی به این مسجد «مزگه‌وتی سوور» می‌گویند که به معنی «مسجد سرخ» است. دلیل نامگذاری این مسجد به «مسجد سرخ»، استفاده از آجرهای قرمزرنگ در نمای آن بوده که جلوه‌ای خاص به بنا بخشیده است. مسجد جامع سرخ نه‌تنها از نظر مذهبی اهمیت دارد، بلکه به‌ عنوان اثر تاریخی ارزشمند، فرهنگ و معماری دوران صفوی را حفظ کرده است.\nآدرس: آذربایجان غربی، مها', 'مسجد جامع مهاباد یکی از آثار تاریخی و مذهبی مهم شهر مهاباد در دوران صفویه است که به دستور حاکم وقت، بداق سلطان ساخته شد و قدمت آن به حدود ۳۵۵ سال پیش بازمی‌گردد. مردم محلی به این مسجد «مزگه‌وتی سوور» می‌گویند که به معنی «مسجد سرخ» است. دلیل نامگذاری این مسجد به «مسجد سرخ»، استفاده از آجرهای قرمزرنگ در نمای آن بوده که جلوه‌ای خاص به بنا بخشیده است. مسجد جامع سرخ نه‌تنها از نظر مذهبی اهمیت دارد، بلکه به‌ عنوان اثر تاریخی ارزشمند، فرهنگ و معماری دوران صفوی را حفظ کرده است.\nآدرس: آذربایجان غربی، مهاباد، محله چهارباغ', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:23:30'),
	(68, '1267702a-2757-46b3-82dc-5e363fa81233', 26, 'آرامگاه شمس تبریزی خوی', 'آرامگاه شمس تبریزی شما را به سفری عمیق در تاریخ و عرفان ایرانی می‌برد. این مکان در دوره صفوی ساخته شده و محل دفن مردی است که مسیر ادبیات و عرفان مولانا را دگرگون کرد. مقبره شمس تبریزی از مناره استوانه‌ای با تزییناتی از شاخ‌های قوچ و جمجمه حیوانات درست شده که علاقه شاه اسماعیل صفوی به شکار کردن را نشان می‌دهد. هر سال در آرامگاه شمس تبریزی، کنگره بین‌المللی به نام این عارف بزرگ (شمس تبریزی) برگزار می‌شود و علاقه‌مندان به مولانا و شمس را از سراسر جهان گرد هم می‌آورد.\nآدرس: آذربایجان غربی، شهرستان خ', 'آرامگاه شمس تبریزی شما را به سفری عمیق در تاریخ و عرفان ایرانی می‌برد. این مکان در دوره صفوی ساخته شده و محل دفن مردی است که مسیر ادبیات و عرفان مولانا را دگرگون کرد. مقبره شمس تبریزی از مناره استوانه‌ای با تزییناتی از شاخ‌های قوچ و جمجمه حیوانات درست شده که علاقه شاه اسماعیل صفوی به شکار کردن را نشان می‌دهد. هر سال در آرامگاه شمس تبریزی، کنگره بین‌المللی به نام این عارف بزرگ (شمس تبریزی) برگزار می‌شود و علاقه‌مندان به مولانا و شمس را از سراسر جهان گرد هم می‌آورد.\nآدرس: آذربایجان غربی، شهرستان خوی، بلوار شمس تبریزی، کوچه زینالی', 38.5566066, 44.9346625, '2026-07-30 20:12:02', '2026-07-30 20:23:32'),
	(69, 'a37a3e76-0de0-4b9f-bb37-499113341cbe', 26, 'آرامگاه پوریای ولی خوی', 'پوریای ولی، یکی از پهلوانان نامدار ایرانی، مقبره‌ای ساده اما با ارزش در خوی دارد. این آرامگاه شامل سنگ قبری ساده، چهار ستون سنگی مسقف و یک انگشتر با حکاکی نام پوریای ولی می‌شود. بعضی از افراد، موقعیت مکانی آرامگاه پوریای ولی را خیوه ازبکستان می‌دانند، در حالی که آرامگاه فرزند ایشان در این لوکیشن قرار دارد.\nآدرس: آذربایجان غربی، خوی، بلوار امام حسین', 'پوریای ولی، یکی از پهلوانان نامدار ایرانی، مقبره‌ای ساده اما با ارزش در خوی دارد. این آرامگاه شامل سنگ قبری ساده، چهار ستون سنگی مسقف و یک انگشتر با حکاکی نام پوریای ولی می‌شود. بعضی از افراد، موقعیت مکانی آرامگاه پوریای ولی را خیوه ازبکستان می‌دانند، در حالی که آرامگاه فرزند ایشان در این لوکیشن قرار دارد.\nآدرس: آذربایجان غربی، خوی، بلوار امام حسین', 38.5454391, 44.9360778, '2026-07-30 20:12:02', '2026-07-30 20:23:37'),
	(70, 'd25cad4c-e6dc-4294-8929-e9c0a86354eb', 26, 'دروازه سنگی خوی', 'دروازه سنگی خوی معروف به «قالا قاپیسی»، تنها دروازه باقی‌مانده از حصار تاریخی شهر است. «قالا قاپیسی» در زبان ترکی به معنای «دروازه قلعه» یا «دروازه حصار» است که نشان می‌دهد این دروازه، شهر را از حملات دشمن حفظ می‌کرد. هنگام سرزدن به دروازه سنگی خوی می‌توانید از بازار تاریخی نزدیک آن هم دیدن کنید. با توجه به سبک معماری دروازه خوی، کارشناسان ساخت آن را به دوره قاجار نسبت می‌دهند. دروازه سنگی خوی طی سال‌ها شاهد حملات ارمنی و عثمانی بوده و آثار گلوله‌های آن‌ها هنوز بر بدنه این دروازه دیده می‌شود.\nآد', 'دروازه سنگی خوی معروف به «قالا قاپیسی»، تنها دروازه باقی‌مانده از حصار تاریخی شهر است. «قالا قاپیسی» در زبان ترکی به معنای «دروازه قلعه» یا «دروازه حصار» است که نشان می‌دهد این دروازه، شهر را از حملات دشمن حفظ می‌کرد. هنگام سرزدن به دروازه سنگی خوی می‌توانید از بازار تاریخی نزدیک آن هم دیدن کنید. با توجه به سبک معماری دروازه خوی، کارشناسان ساخت آن را به دوره قاجار نسبت می‌دهند. دروازه سنگی خوی طی سال‌ها شاهد حملات ارمنی و عثمانی بوده و آثار گلوله‌های آن‌ها هنوز بر بدنه این دروازه دیده می‌شود.\nآدرس: آذربایجان غربی، خوی، خیابان طالقانی، جنوب بازار خوی', 38.5478935, 44.9602463, '2026-07-30 20:12:02', '2026-07-30 20:23:40'),
	(71, '015bc1eb-1f61-4d40-aae9-954a1f1636b1', 26, 'بازار خوی', 'بازار خوی دومین بازار بزرگ ایران است که قدمت آن به دوران صفویه بازمی‌گردد. این بازار در گذشته یکی از مراکز تجاری مهم کشور بود زیرا در مسیرهای راه مکه، جاده ابریشم و جلفا قرار داشت. بازار خوی شامل مجموعه‌ای از راسته‌ها، چهارسوها و سراهای متعدد است که هنوز هم پس از قرن‌ها، جذابیت و رونق دارند. براساس کتیبه‌ای که هم‌اکنون در گنجینه خوی نگهداری می‌شود، این بازار در زمان شاه طهماسب صفوی ساخته شده است.\nآدرس: آذربایجان غربی، خوی، ضلع جنوب شرقی چهارراه مرکزی، خیابان طالقانی\nساعت کاری: هر روز از ۸ صبح تا', 'بازار خوی دومین بازار بزرگ ایران است که قدمت آن به دوران صفویه بازمی‌گردد. این بازار در گذشته یکی از مراکز تجاری مهم کشور بود زیرا در مسیرهای راه مکه، جاده ابریشم و جلفا قرار داشت. بازار خوی شامل مجموعه‌ای از راسته‌ها، چهارسوها و سراهای متعدد است که هنوز هم پس از قرن‌ها، جذابیت و رونق دارند. براساس کتیبه‌ای که هم‌اکنون در گنجینه خوی نگهداری می‌شود، این بازار در زمان شاه طهماسب صفوی ساخته شده است.\nآدرس: آذربایجان غربی، خوی، ضلع جنوب شرقی چهارراه مرکزی، خیابان طالقانی\nساعت کاری: هر روز از ۸ صبح تا ۱۶', 38.5498420, 44.9603142, '2026-07-30 20:12:02', '2026-07-30 20:23:42'),
	(72, 'a4840499-9bef-41df-afdf-f233054709e0', 26, 'مقبره آل یعقوب خوی', 'از بین دیدنی‌های تاریخی و زیارتی خوی، این بار سراغ مقبره آل یعقوب می‌رویم که در بافت قدیمی شهر و کنار بازار قرار دارد. این آرامگاه در واقع خانه میر یعقوب کوه‌کمری، عالم و قاضی بزرگ خوی بوده که پس از ۴۰ سقره ال قضاوت در این شهر، در همین خانه به خاک سپرده شد. ساختمان این خانه‌، سه در اصلی دارد و نمای آن با کاشی‌های هفت‌رنگ، طرح گل و بوته، خورشید و شیر تزیین شده و کتیبه‌ای از آیات قرآن روی یکی از دیوارهای آن نصب شده است.\nآدرس: خوی، خیابان طالقانی، روبه‌روی ضلع غربی بازار قدیمی', 'از بین دیدنی‌های تاریخی و زیارتی خوی، این بار سراغ مقبره آل یعقوب می‌رویم که در بافت قدیمی شهر و کنار بازار قرار دارد. این آرامگاه در واقع خانه میر یعقوب کوه‌کمری، عالم و قاضی بزرگ خوی بوده که پس از ۴۰ سقره ال قضاوت در این شهر، در همین خانه به خاک سپرده شد. ساختمان این خانه‌، سه در اصلی دارد و نمای آن با کاشی‌های هفت‌رنگ، طرح گل و بوته، خورشید و شیر تزیین شده و کتیبه‌ای از آیات قرآن روی یکی از دیوارهای آن نصب شده است.\nآدرس: خوی، خیابان طالقانی، روبه‌روی ضلع غربی بازار قدیمی', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:23:50'),
	(73, '37d3c25d-76ca-4a1a-856b-b84d81a1999f', 26, 'آبشار بدلان', 'آبشار بدلان که با نام آبشار قزل‌چیر نیز شناخته می‌شود، در منطقه‌ای سرسبز و خوش‌آب‌وهوا قرار دارد. این آبشار بیش از ۵۰ متر ارتفاع دارد و از گودالی غارمانند سرچشمه می‌گیرد.\nآدرس: آذربایجان غربی، ۲۱ کیلومتری خوی، روستای بدلان', 'آبشار بدلان که با نام آبشار قزل‌چیر نیز شناخته می‌شود، در منطقه‌ای سرسبز و خوش‌آب‌وهوا قرار دارد. این آبشار بیش از ۵۰ متر ارتفاع دارد و از گودالی غارمانند سرچشمه می‌گیرد.\nآدرس: آذربایجان غربی، ۲۱ کیلومتری خوی، روستای بدلان', 38.6001820, 44.6649086, '2026-07-30 20:12:02', '2026-07-30 20:23:53'),
	(74, '7664047e-bc6d-49d3-867c-fbc1f64f0be7', 26, 'تپه حسنلو نقده', 'تپه حسنلو نقده در نزدیکی شهرستان نقده یکی از مهم‌ترین جاذبه‌های تاریخی ایران است که قدمت آن به حدود ۶ هزار سال پیش می‌رسد. از آنجا که تپه حسنلو در دوره‌های مختلف تاریخی به صورت مسکونی بوده، آثار ارزشمندی از تمدن‌های مختلف در آن وجود دارد. یکی از مهم‌ترین آثار تاریخی این منطقه، «جام زرین حسنلو» است که متعلق به دوره آهن بوده و در موزه ملی ایران نگهداری می‌شود.\nآدرس: آذربایجان غربی، ۱۲ کیلومتری شمال‌شرقی شهرستان نقده، نزدیک روستای حسنلو', 'تپه حسنلو نقده در نزدیکی شهرستان نقده یکی از مهم‌ترین جاذبه‌های تاریخی ایران است که قدمت آن به حدود ۶ هزار سال پیش می‌رسد. از آنجا که تپه حسنلو در دوره‌های مختلف تاریخی به صورت مسکونی بوده، آثار ارزشمندی از تمدن‌های مختلف در آن وجود دارد. یکی از مهم‌ترین آثار تاریخی این منطقه، «جام زرین حسنلو» است که متعلق به دوره آهن بوده و در موزه ملی ایران نگهداری می‌شود.\nآدرس: آذربایجان غربی، ۱۲ کیلومتری شمال‌شرقی شهرستان نقده، نزدیک روستای حسنلو', 37.0044038, 45.4580077, '2026-07-30 20:12:02', '2026-07-30 20:23:55'),
	(75, 'efb4a9d9-a2e5-47bb-b6f9-9a15f37d0328', 26, 'تالاب شیطان آباد', 'یکی از جاهای دیدنی آذربایجان غربی در زمستان، تالاب شیطان‌آباد در ۶ کیلومتری نقده است که زیستگاه مهمی برای پرندگان مهاجر در فصل سرد به شمار می‌رود. برای رسیدن به این تالاب باید از شهرستان نقده به سمت روستای حیدرآباد حرکت کرده و در سمت شرقی جاده، تابلوهای راهنما را دنبال کنید.\nآدرس: آذربایجان غربی، ۶ کیلومتری شمال‌ شرقی شهرستان نقده، سمت شرقی جاده شوسه نقده-حیدرآباد\nهزینه ورودی: رایگان', 'یکی از جاهای دیدنی آذربایجان غربی در زمستان، تالاب شیطان‌آباد در ۶ کیلومتری نقده است که زیستگاه مهمی برای پرندگان مهاجر در فصل سرد به شمار می‌رود. برای رسیدن به این تالاب باید از شهرستان نقده به سمت روستای حیدرآباد حرکت کرده و در سمت شرقی جاده، تابلوهای راهنما را دنبال کنید.\nآدرس: آذربایجان غربی، ۶ کیلومتری شمال‌ شرقی شهرستان نقده، سمت شرقی جاده شوسه نقده-حیدرآباد\nهزینه ورودی: رایگان', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:24:03'),
	(76, '980fcaf2-b537-49c7-b8d9-1e9469317003', 26, 'تالاب حسنلو', 'تالاب حسنلو مورد بعدی از بهترین جاهای دیدنی آذربایجان غربی است که حدود هزار هکتار مساحت دارد. این تالاب دریاچه‌ای کم‌عمق بوده و آب آن از باران، چشمه‌ها و جویبارها تامین می‌شود. این تالاب بهترین جاذبه برای افرادی است که دوست دارند پرندگانی خاص را ببینند.\nآدرس: آذربایجان غربی، شهرستان نقده، بخش محمدیار، دهستان حسنلو، ۶ کیلومتری شمال روستای شیخ احمد', 'تالاب حسنلو مورد بعدی از بهترین جاهای دیدنی آذربایجان غربی است که حدود هزار هکتار مساحت دارد. این تالاب دریاچه‌ای کم‌عمق بوده و آب آن از باران، چشمه‌ها و جویبارها تامین می‌شود. این تالاب بهترین جاذبه برای افرادی است که دوست دارند پرندگانی خاص را ببینند.\nآدرس: آذربایجان غربی، شهرستان نقده، بخش محمدیار، دهستان حسنلو، ۶ کیلومتری شمال روستای شیخ احمد', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:24:11'),
	(77, 'c958e2be-5dec-471c-b6f2-a01c9d8b068a', 26, 'پل ممیند یا بهراملو', 'پل ممیند شاهکاری از معماری ایرانی است که قدمت آن به دوره‌های صفویه و قاجار نسبت داده می‌شود. بدنه این پل از آجر و ملات ساخته شده و با سنگ‌فرش پوشیده شده است. این اثر تاریخی نه تنها از نظر معماری ارزشمند بوده، بلکه به‌ عنوان شاهراه ارتباطی بین شهرهای مهاباد، ارومیه و نقده در گذشته نیز اهمیت داشت. موقعیت پل و بقایای جاده قدیمی، از یک راه قدیمی بین این سه شهر، حکایت می‌کند.\nآدرس: آذربایجان غربی، نقده، ۷ کیلومتری شمال شرقی سه راهی نقده', 'پل ممیند شاهکاری از معماری ایرانی است که قدمت آن به دوره‌های صفویه و قاجار نسبت داده می‌شود. بدنه این پل از آجر و ملات ساخته شده و با سنگ‌فرش پوشیده شده است. این اثر تاریخی نه تنها از نظر معماری ارزشمند بوده، بلکه به‌ عنوان شاهراه ارتباطی بین شهرهای مهاباد، ارومیه و نقده در گذشته نیز اهمیت داشت. موقعیت پل و بقایای جاده قدیمی، از یک راه قدیمی بین این سه شهر، حکایت می‌کند.\nآدرس: آذربایجان غربی، نقده، ۷ کیلومتری شمال شرقی سه راهی نقده', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:24:19'),
	(78, 'ee172d14-eb09-44a1-a0e2-56332c572982', 26, 'موزه نقده', 'موزه نقده در سال ۱۳۷۹ با هدف معرفی آثار باستانی منطقه و تپه تاریخی حسنلو تاسیس شد و به عنوان موزه باستان‌شناسی فعالیت می‌کند. در این موزه، یک سالن نمایش با ویترین‌های چوبی ساخته شده که آثار مختلفی را به نمایش می‌گذارد. در موزه نقده، اشیایی مانند سفالینه‌ها، ظروف مفرغی (مِفرَغ که در فارسی به آن «برنز» نیز گفته می‌شود، آلیاژی از مس و قلع بوده که ساخت آن به حدود پنج هزار سال قبل بازمی‌گردد)، آجرهای لعابدار، مهرها و وسایل تزئینی وجود دارد که تمدن‌ باستانی این منطقه را نشان می‌دهد.\nآدرس: آذربایجان غر', 'موزه نقده در سال ۱۳۷۹ با هدف معرفی آثار باستانی منطقه و تپه تاریخی حسنلو تاسیس شد و به عنوان موزه باستان‌شناسی فعالیت می‌کند. در این موزه، یک سالن نمایش با ویترین‌های چوبی ساخته شده که آثار مختلفی را به نمایش می‌گذارد. در موزه نقده، اشیایی مانند سفالینه‌ها، ظروف مفرغی (مِفرَغ که در فارسی به آن «برنز» نیز گفته می‌شود، آلیاژی از مس و قلع بوده که ساخت آن به حدود پنج هزار سال قبل بازمی‌گردد)، آجرهای لعابدار، مهرها و وسایل تزئینی وجود دارد که تمدن‌ باستانی این منطقه را نشان می‌دهد.\nآدرس: آذربایجان غربی، نقده، خیابان امام، خیابان پاسداران ۲، پارک لاله\nساعت بازدید: هر روز از ۹ صبح تا ۱۹\nقیمت بلیط: ۴ هزار تومان', 36.9556390, 45.3869954, '2026-07-30 20:12:02', '2026-07-30 20:24:21'),
	(79, '4ae205a2-02e1-4cc2-b009-cb1401517353', 26, 'تپه حاجی فیروز', 'تپه حاجی فیروز یکی از مهم‌ترین سایت‌های باستان‌شناسی و آثار ملی کشور است که قدمت آن به ۵ هزار سال پیش از میلاد می‌رسد. در این محوطه باستانی، بقایای ۱۸ ساختمان با نقشه‌های مربع‌شکل کشف شده که دیوارهای بزرگی دارند. این خانه‌های قدیمی دارای اتاق‌های نشیمن، آشپزخانه و انبارهای آذوقه هستند. عجیب است اما واقعی که در برخی موارد، اجساد کودکان در این مکان‌ها دفن شده‌اند. آثار کشف‌شده از تپه حاجی فیروز شامل اشیای سنگی، گلی، استخوانی، صدفی و ظروف سفالی با نقش‌های هندسی و خطی می‌شوند.\nآدرس: آذربایجان غربی، ', 'تپه حاجی فیروز یکی از مهم‌ترین سایت‌های باستان‌شناسی و آثار ملی کشور است که قدمت آن به ۵ هزار سال پیش از میلاد می‌رسد. در این محوطه باستانی، بقایای ۱۸ ساختمان با نقشه‌های مربع‌شکل کشف شده که دیوارهای بزرگی دارند. این خانه‌های قدیمی دارای اتاق‌های نشیمن، آشپزخانه و انبارهای آذوقه هستند. عجیب است اما واقعی که در برخی موارد، اجساد کودکان در این مکان‌ها دفن شده‌اند. آثار کشف‌شده از تپه حاجی فیروز شامل اشیای سنگی، گلی، استخوانی، صدفی و ظروف سفالی با نقش‌های هندسی و خطی می‌شوند.\nآدرس: آذربایجان غربی، شهرستان نقده، بخش محمدیار، دهستان حسنلو، روستای حاجی فیروز', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:24:29'),
	(80, 'ef4bc169-6d54-494c-b0af-45aee6137e61', 26, 'کوه سلطان یعقوب', 'اگر بخواهیم یکی دیگر از دیدنی های آذربایجان غربی را معرفی کنیم، نوبت به کوه سلطان یعقوب می‌رسد. این منطقه نه تنها به خاطر مناظر طبیعی، بلکه با مسیرهای زیبای کوهنوردی خود، مورد توجه کوهنوردان قرار می‌گیرد. وجه تسمیه کوه سلطان یعقوب به یک شخصیت تاریخی محلی نسبت داده می‌شود که فرمانده‌ این منطقه بوده و نام او را به یادگار بر این کوه گذاشته‌اند.\nآدرس: آذربایجان غربی، ۵ کیلومتری شهر نقده', 'اگر بخواهیم یکی دیگر از دیدنی های آذربایجان غربی را معرفی کنیم، نوبت به کوه سلطان یعقوب می‌رسد. این منطقه نه تنها به خاطر مناظر طبیعی، بلکه با مسیرهای زیبای کوهنوردی خود، مورد توجه کوهنوردان قرار می‌گیرد. وجه تسمیه کوه سلطان یعقوب به یک شخصیت تاریخی محلی نسبت داده می‌شود که فرمانده‌ این منطقه بوده و نام او را به یادگار بر این کوه گذاشته‌اند.\nآدرس: آذربایجان غربی، ۵ کیلومتری شهر نقده', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:24:37'),
	(81, '23e15861-f178-41ab-b86d-58691df254cf', 26, 'گردشگاه هفت چشمه', 'تفرجگاه هفت چشمه در میان اهالی به نام «یئدی گؤز» (به معنی هفت چشم) معروف است که از هفت چشمه مختلف و تجمع آنها در یک حوض میانی شکل می‌گیرد. بر اساس باور مردم محلی‌، آب هر یک از این چشمه‌ها طعم خاصی دارند. این تفرجگاه در دامنه کوهستان سلطان یعقوب واقع شده و امکاناتی مانند آلاچیق، شهربازی، پارکینگ، رستوران و حتی در زمستان امکانات بازی‌های برفی و تیوپ‌سواری را دارد.\nآدرس : آذربایجان غربی، جنوب غربی شهرستان نقده، قسمت شرقی سلطان یعقوب', 'تفرجگاه هفت چشمه در میان اهالی به نام «یئدی گؤز» (به معنی هفت چشم) معروف است که از هفت چشمه مختلف و تجمع آنها در یک حوض میانی شکل می‌گیرد. بر اساس باور مردم محلی‌، آب هر یک از این چشمه‌ها طعم خاصی دارند. این تفرجگاه در دامنه کوهستان سلطان یعقوب واقع شده و امکاناتی مانند آلاچیق، شهربازی، پارکینگ، رستوران و حتی در زمستان امکانات بازی‌های برفی و تیوپ‌سواری را دارد.\nآدرس : آذربایجان غربی، جنوب غربی شهرستان نقده، قسمت شرقی سلطان یعقوب', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:24:45'),
	(82, '468fdb18-abd1-4fa2-a239-3ded7f27e8f0', 26, 'تالاب آق زیارت', 'تالاب آق‌ زیارت یکی از جاذبه‌های طبیعی و بکر استان آذربایجان غربی در شهرستان سلماس است. این تالاب زیستگاه مناسبی برای انواع پرندگان مهاجر و بومی به‌ ویژه در فصل‌های پاییز و زمستان به شمار می‌رود. برای دسترسی به تالاب آق‌زیارت، باید از شهر سلماس به سمت روستای آق‌زیارت حرکت کنید. البته بهتر است قبل از سفر، وضعیت جاده‌ها و شرایط آب‌وهوایی این منطقه را بررسی کنید تا نهایت لذت را از مسافرت خود ببرید.\nآدرس: آذربایجان غربی، ۲۰ کیلومتری سلماس', 'تالاب آق‌ زیارت یکی از جاذبه‌های طبیعی و بکر استان آذربایجان غربی در شهرستان سلماس است. این تالاب زیستگاه مناسبی برای انواع پرندگان مهاجر و بومی به‌ ویژه در فصل‌های پاییز و زمستان به شمار می‌رود. برای دسترسی به تالاب آق‌زیارت، باید از شهر سلماس به سمت روستای آق‌زیارت حرکت کنید. البته بهتر است قبل از سفر، وضعیت جاده‌ها و شرایط آب‌وهوایی این منطقه را بررسی کنید تا نهایت لذت را از مسافرت خود ببرید.\nآدرس: آذربایجان غربی، ۲۰ کیلومتری سلماس', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:24:54'),
	(83, '96821553-711e-4123-aea3-d7fe711ff10b', 26, 'کلیسای سرکیس مقدس', 'یکی از جاذبه‌های دیدنی در اطراف شهر سلماس، کلیسای سرکیس مقدس در روستای قلعه سر بوده که قدمت آن به سال ۱۸۰۶ میلادی بازمی‌گردد. این کلیسا توسط اهالی ارمنی روستا ساخته شده و امروزه تنها بخش جنوبی آن سالم مانده است. روی سنگ‌ دیوارهای کلیسای سرکیس مقدس، نوشته‌هایی به زبان ارمنی و چند صلیب وجود دارد. در فضای داخلی این کلیسا، نقاشی‌ها و کتیبه‌های مذهبی نقش بسته که داستان‌هایی از ایمان و تاریخ مسیحیت را روایت می‌کنند.\nآدرس: آذربایجان غربی، سلماس، روستای قلعه سر', 'یکی از جاذبه‌های دیدنی در اطراف شهر سلماس، کلیسای سرکیس مقدس در روستای قلعه سر بوده که قدمت آن به سال ۱۸۰۶ میلادی بازمی‌گردد. این کلیسا توسط اهالی ارمنی روستا ساخته شده و امروزه تنها بخش جنوبی آن سالم مانده است. روی سنگ‌ دیوارهای کلیسای سرکیس مقدس، نوشته‌هایی به زبان ارمنی و چند صلیب وجود دارد. در فضای داخلی این کلیسا، نقاشی‌ها و کتیبه‌های مذهبی نقش بسته که داستان‌هایی از ایمان و تاریخ مسیحیت را روایت می‌کنند.\nآدرس: آذربایجان غربی، سلماس، روستای قلعه سر', 35.7149404, 51.4151007, '2026-07-30 20:12:02', '2026-07-30 20:24:58'),
	(84, 'dcb1ddf0-c7fc-4440-bd93-0825371e5f29', 26, 'کلیسای محلم', 'در معرفی جاهای دیدنی آذربایجان غربی در شهر سلماس، دوباره سراغ کلیسایی دیگر به نام محلم می‌رویم. تاریخ ساخت این کلیسا به سال ۱۸۸۰ میلادی بازمی‌گردد، اما در ورودی آن، تاریخ ۱۸۹۵ میلادی به چشم می‌خورد که تاریخ تعمیرات یا بازسازی‌ آن را نشان می‌دهد. متاسفانه، از بنای اصلی کلیسای محلم جز در ورودی و چند طاق نیمه‌فرو ریخته، چیزی باقی نمانده است.\nآدرس : آذربایجان غربی، شهرستان سلماس، بخش مرکزی، روستای محلم', 'در معرفی جاهای دیدنی آذربایجان غربی در شهر سلماس، دوباره سراغ کلیسایی دیگر به نام محلم می‌رویم. تاریخ ساخت این کلیسا به سال ۱۸۸۰ میلادی بازمی‌گردد، اما در ورودی آن، تاریخ ۱۸۹۵ میلادی به چشم می‌خورد که تاریخ تعمیرات یا بازسازی‌ آن را نشان می‌دهد. متاسفانه، از بنای اصلی کلیسای محلم جز در ورودی و چند طاق نیمه‌فرو ریخته، چیزی باقی نمانده است.\nآدرس : آذربایجان غربی، شهرستان سلماس، بخش مرکزی، روستای محلم', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:25:06'),
	(85, 'c6cab4bb-9e1f-4943-aa7a-93cdb6ab356c', 26, 'کلیسای گئورگ مقدس هفتوان', 'کلیسای گئورگ مقدس هفتوان یکی از آثار تاریخی و مذهبی سلماس است که در اواخر دوره صفوی به دستور شاه‌عباس صفوی ساخته شد. در نمای این کلیسا از سنگ‌های سیاه‌رنگ استفاده شده و هم‌چنین در دیوارهای ورودی آن، کتیبه‌هایی به خط ارمنی مشاهده می‌شود که تاریخ ساخت و وقایع مرتبط با کلیسا را ثبت کرده‌اند. در کنار این جاذبه تاریخی، بقایای تئاتر هفتوان نیز قرار دارد که در دوران اشغال روس‌ها در جنگ جهانی اول ساخته شد و از آن به عنوان محل برگزاری تئاتر استفاده می‌کردند.\nآدرس: نزدیک روستای مرگن، بین ماکو و قره ضیاالد', 'کلیسای گئورگ مقدس هفتوان یکی از آثار تاریخی و مذهبی سلماس است که در اواخر دوره صفوی به دستور شاه‌عباس صفوی ساخته شد. در نمای این کلیسا از سنگ‌های سیاه‌رنگ استفاده شده و هم‌چنین در دیوارهای ورودی آن، کتیبه‌هایی به خط ارمنی مشاهده می‌شود که تاریخ ساخت و وقایع مرتبط با کلیسا را ثبت کرده‌اند. در کنار این جاذبه تاریخی، بقایای تئاتر هفتوان نیز قرار دارد که در دوران اشغال روس‌ها در جنگ جهانی اول ساخته شد و از آن به عنوان محل برگزاری تئاتر استفاده می‌کردند.\nآدرس: نزدیک روستای مرگن، بین ماکو و قره ضیاالدین، جنوب‌شرقی روستای شوط', 38.1700183, 44.7564836, '2026-07-30 20:12:02', '2026-07-30 20:25:08'),
	(86, '5765352c-bcdb-4f53-9f54-b9a016cde01f', 26, 'کلیسای مارسرکیس', 'کلیسای قدیمی مارسرکیس یکی از دیدنی های آذربایجان غربی است که تاریخ ساخت آن به دوران قاجار می‌رسد؛ هر چند برخی از محلی‌ها معتقدند که قدمت آن به دوران ساسانیان برمی‌گردد. صلیب مقدس حضرت مسیح که توسط خسرو پرویز از اورشلیم به ایران آورده شد، در کلیسای مارسرکیس نگهداری می‌شد. در زمان پادشاهی پوران‌دخت (پادشاه زن ایرانی)، این صلیب هنگام برقراری صلح میان ایران و روم، به دربار روم اهدا شد.\nآدرس: سلماس، روستای خسروآباد', 'کلیسای قدیمی مارسرکیس یکی از دیدنی های آذربایجان غربی است که تاریخ ساخت آن به دوران قاجار می‌رسد؛ هر چند برخی از محلی‌ها معتقدند که قدمت آن به دوران ساسانیان برمی‌گردد. صلیب مقدس حضرت مسیح که توسط خسرو پرویز از اورشلیم به ایران آورده شد، در کلیسای مارسرکیس نگهداری می‌شد. در زمان پادشاهی پوران‌دخت (پادشاه زن ایرانی)، این صلیب هنگام برقراری صلح میان ایران و روم، به دربار روم اهدا شد.\nآدرس: سلماس، روستای خسروآباد', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:25:15'),
	(87, '039412cd-cff3-4bb7-897d-d1b9277b4aeb', 26, 'کلیسای آخته خانه', 'در لیست جاهای دیدنی آذربایجان غربی در سلماس به کلیسای آخته خانه می‌رسیم. نام «آخته خانه» در زبان ارمنی به‌ معنای «خانه دختر» است که احتمالا به‌ حضور خانواده‌های ارمنی در منطقه کلیسا اشاره دارد. در سالن اصلی کلیسا، چهار ستون دایره‌ای را می‌بینید که مصالح به‌ کار رفته در آن شامل سنگ لاشه، آجر و ملات آهک می‌شود.\nآدرس: آذربایجان غربی، شهرستان سلماس، روستای اخته‌خانه', 'در لیست جاهای دیدنی آذربایجان غربی در سلماس به کلیسای آخته خانه می‌رسیم. نام «آخته خانه» در زبان ارمنی به‌ معنای «خانه دختر» است که احتمالا به‌ حضور خانواده‌های ارمنی در منطقه کلیسا اشاره دارد. در سالن اصلی کلیسا، چهار ستون دایره‌ای را می‌بینید که مصالح به‌ کار رفته در آن شامل سنگ لاشه، آجر و ملات آهک می‌شود.\nآدرس: آذربایجان غربی، شهرستان سلماس، روستای اخته‌خانه', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:25:23'),
	(88, '60f99d71-f486-4bef-92af-6f80b6ccb583', 26, 'آبشار خورخوره (ممکان)', 'آبشار دره خورخوره در دل دره‌ای عمیق به عمق حدود ۸۰ متر جای گرفته و از میان صخره‌های سخت و بلند به پایین می‌ریزد. ارتفاع این آبشار نزدیک ۳۵ متر است و پس از ریزش از بالای آبشار، حوضچه‌ای زیبا شکل می‌گیرد. دور تا دور این حوضچه را دیواره‌های سنگی احاطه کرده‌اند که روی آن‌ها خزه‌های سبز و نم‌خورده دیده می‌شود.\nآدرس: آذربایجان غربی، شهرستان سلماس، حد فاصل روستاهای سرگل و ممکان', 'آبشار دره خورخوره در دل دره‌ای عمیق به عمق حدود ۸۰ متر جای گرفته و از میان صخره‌های سخت و بلند به پایین می‌ریزد. ارتفاع این آبشار نزدیک ۳۵ متر است و پس از ریزش از بالای آبشار، حوضچه‌ای زیبا شکل می‌گیرد. دور تا دور این حوضچه را دیواره‌های سنگی احاطه کرده‌اند که روی آن‌ها خزه‌های سبز و نم‌خورده دیده می‌شود.\nآدرس: آذربایجان غربی، شهرستان سلماس، حد فاصل روستاهای سرگل و ممکان', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:25:31'),
	(89, '4b79b84c-aa95-4957-a3f4-c9dbe3860010', 26, 'گوردخمه هدر سلماس', 'گوردخمه هدر یکی دیگر از آثار باستانی شهرستان سلماس است که شامل دو دخمه معروف به نام‌های «دخمه دختر» و «دخمه پسر» می‌شود. قدمت این گوردخمه‌ها به دوره‌های پیش از اسلام برمی‌گردد و احتمالا قبرهای بزرگان و خاندان‌های سلطنتی این منطقه بوده‌اند. معماری این دخمه‌ها ساده است و از سنگ‌های طبیعی ساخته شده‌اند تا در برابر خطرات طبیعی مانند زمین‌لرزه و سیل محفوظ بمانند.\nآدرس: آذربایجان غربی، سلماس، روستای هدر، کوه‌های شوریک', 'گوردخمه هدر یکی دیگر از آثار باستانی شهرستان سلماس است که شامل دو دخمه معروف به نام‌های «دخمه دختر» و «دخمه پسر» می‌شود. قدمت این گوردخمه‌ها به دوره‌های پیش از اسلام برمی‌گردد و احتمالا قبرهای بزرگان و خاندان‌های سلطنتی این منطقه بوده‌اند. معماری این دخمه‌ها ساده است و از سنگ‌های طبیعی ساخته شده‌اند تا در برابر خطرات طبیعی مانند زمین‌لرزه و سیل محفوظ بمانند.\nآدرس: آذربایجان غربی، سلماس، روستای هدر، کوه‌های شوریک', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:25:40'),
	(90, 'd724b21b-a9fc-454a-abd2-0a0d4397c461', 26, 'نقش برجسته خان تختی', 'نقش‌ برجسته خان تختی سلماس یکی از حوادث تاریخی شمال‌ غرب ایران را روایت می‌کند. در تصویر این نقش برجسته، دو نفر به‌صورت پیاده و دو نفر سواره دیده می‌شوند. شخص سواره سمت چپ، اردشیر بابکان بنیان‌گذار سلسله ساسانی و شخص سواره سمت راست، شاپور یکم ولیعهد و پسر اردشیر است. در نقش برجسته خان تختی، والریانوس پادشاه روم در مقابل شاپور زانو زده و دو حاکم محلی ارمنی در حال تقدیم هدایا به اردشیر و شاپور هستند. این پیروزی تاریخی چنان مهم بوده که پادشاه ساسانی دستور حکاکی آن را بر کوه پیرچاوش را صادر کرده است', 'نقش‌ برجسته خان تختی سلماس یکی از حوادث تاریخی شمال‌ غرب ایران را روایت می‌کند. در تصویر این نقش برجسته، دو نفر به‌صورت پیاده و دو نفر سواره دیده می‌شوند. شخص سواره سمت چپ، اردشیر بابکان بنیان‌گذار سلسله ساسانی و شخص سواره سمت راست، شاپور یکم ولیعهد و پسر اردشیر است. در نقش برجسته خان تختی، والریانوس پادشاه روم در مقابل شاپور زانو زده و دو حاکم محلی ارمنی در حال تقدیم هدایا به اردشیر و شاپور هستند. این پیروزی تاریخی چنان مهم بوده که پادشاه ساسانی دستور حکاکی آن را بر کوه پیرچاوش را صادر کرده است.\nآدرس: آذربایجان غربی، ۱۵ کیلومتری جاده سلماس به ارومیه، نزدیکی روستای خان تختی', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:25:48'),
	(91, '17b937fe-30fb-40d7-a6d2-26d10192e302', 26, 'حمام شیخ سلماس', 'حمام شیخ سلماس یادگاری باشکوه از دوران پهلوی اول (۱۳۰۹ تا ۱۳۱۲) است. بخش‌های مختلف این حمام شامل سربینه، گرمخانه، خزینه و گنبد بزرگ با نورپردازی طبیعی می‌شود. حمام شیخ سلماس در گذشته فقط مکانی برای شستشو نبود، بلکه محلی برای تعاملات اجتماعی، فرهنگی و حتی مذهبی مردم بود.\nآدرس: سلماس، خیابان امام خمینی، خیابان سوره‌ای', 'حمام شیخ سلماس یادگاری باشکوه از دوران پهلوی اول (۱۳۰۹ تا ۱۳۱۲) است. بخش‌های مختلف این حمام شامل سربینه، گرمخانه، خزینه و گنبد بزرگ با نورپردازی طبیعی می‌شود. حمام شیخ سلماس در گذشته فقط مکانی برای شستشو نبود، بلکه محلی برای تعاملات اجتماعی، فرهنگی و حتی مذهبی مردم بود.\nآدرس: سلماس، خیابان امام خمینی، خیابان سوره‌ای', 38.1948699, 44.7670226, '2026-07-30 20:12:02', '2026-07-30 20:25:50'),
	(92, '7a850c5e-79de-4d80-a789-42445ebf20d9', 26, 'قلعه چهریق', 'قلعه تاریخی چهریق در نزدیکی روستای چهریق از توابع شهرستان سلماس قرار گرفته و قدمت آن به هزاره اول قبل از میلاد و دوران اورارتویی‌ها بازمی‌گردد. این قلعه در روزگاران دور، زندان سید علی محمد باب، پیشوای آیین بیانی بوده است.\nآدرس: شهرستان سلماس، جاده اسکندیان، جاده بستک‌آباد', 'قلعه تاریخی چهریق در نزدیکی روستای چهریق از توابع شهرستان سلماس قرار گرفته و قدمت آن به هزاره اول قبل از میلاد و دوران اورارتویی‌ها بازمی‌گردد. این قلعه در روزگاران دور، زندان سید علی محمد باب، پیشوای آیین بیانی بوده است.\nآدرس: شهرستان سلماس، جاده اسکندیان، جاده بستک‌آباد', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:25:59'),
	(93, 'dd4c1ae9-a9a8-4081-8d40-43ffb2fb594f', 26, 'قره کلیسا چالدران', 'قره کلیسا یا کلیسای تادئوس مقدس، یکی از قدیمی‌ترین کلیساها و به نظر برخی از باستان‌شناسان، اولین کلیسای جهان است. این کلیسا روی مزار تادئوس مقدس (یکی از حواریون حضرت مسیح) ساخته شده و همین موضوع، اهمیت مذهبی آن را دوچندان کرده است. بعضی از روایت‌های تاریخی می‌گویند تادئوس برای تبلیغ مسیحیت به این منطقه آمد، اما پادشاه وقت پس از تغییر عقیده، دستور قتل او و همراهانش را صادر کرد و پیکر تادئوس در مکان فعلی کلیسا به خاک سپرده شد.\nقره‌کلیسا به معنای سیاه است و به این موضوع اشاره دارد که بنای اصلی این ', 'قره کلیسا یا کلیسای تادئوس مقدس، یکی از قدیمی‌ترین کلیساها و به نظر برخی از باستان‌شناسان، اولین کلیسای جهان است. این کلیسا روی مزار تادئوس مقدس (یکی از حواریون حضرت مسیح) ساخته شده و همین موضوع، اهمیت مذهبی آن را دوچندان کرده است. بعضی از روایت‌های تاریخی می‌گویند تادئوس برای تبلیغ مسیحیت به این منطقه آمد، اما پادشاه وقت پس از تغییر عقیده، دستور قتل او و همراهانش را صادر کرد و پیکر تادئوس در مکان فعلی کلیسا به خاک سپرده شد.\nقره‌کلیسا به معنای سیاه است و به این موضوع اشاره دارد که بنای اصلی این کلیسا از سنگ‌های سیاه و سفید ساخته شده است. هر سال در اوایل تابستان، مراسم زیارتی ارمنی‌ها با عنوان «زیارت کلیسای تادئوس مقدس» در این کلیسا برگزار می‌شود.\nآدرس: آذربایجان غربی، ۲۰ کیلومتری شمال شرقی چالدران، روستای قره کلیسا\nساعت بازدید: نیمه اول سال از ۹ صبح تا ۲۰ و نیمه دوم سال از ۹ صبح تا ۱۷\nهزینه بلیط: 25 هزار تومان', 39.0923665, 44.5443813, '2026-07-30 20:12:02', '2026-07-30 20:26:01'),
	(94, 'e7416a37-4e63-4b66-8cc8-062fd4d41dbc', 26, 'دریاچه سد بارون', 'سد بارون در جنوب ماکو روی رودخانه‌ زنگمار قرار گرفته و یکی از بزرگ‌ترین سدهای این منطقه به‌ شمار می‌آید. وجود دریاچه‌ای بزرگ با چشم‌اندازهای زیبا، این مکان را به مقصدی جذاب برای دوستداران طبیعت تبدیل کرده است. ورود به محدوده این سد به دلیل مسائل امنیتی، فقط با هماهنگی و کسب اجازه از نگهبانی امکان‌‌پذیر است.\nآدرس: شهرستان چالدران، خیابان رسالت، خیابان انتظام', 'سد بارون در جنوب ماکو روی رودخانه‌ زنگمار قرار گرفته و یکی از بزرگ‌ترین سدهای این منطقه به‌ شمار می‌آید. وجود دریاچه‌ای بزرگ با چشم‌اندازهای زیبا، این مکان را به مقصدی جذاب برای دوستداران طبیعت تبدیل کرده است. ورود به محدوده این سد به دلیل مسائل امنیتی، فقط با هماهنگی و کسب اجازه از نگهبانی امکان‌‌پذیر است.\nآدرس: شهرستان چالدران، خیابان رسالت، خیابان انتظام', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:26:09'),
	(95, 'e7011008-5634-4ff4-945c-ab1f95c761a5', 26, 'مقبره شیخ صدرالدین', 'در دل دشت‌های وسیع چالدران، آرامگاه سید صدرالدین صفوی قرار گرفته که این شخص، وزیر اعظم شاه اسماعیل اول صفوی بوده است. سید صدرالدین در جنگ چالدران با ۲۷ هزار سرباز در آن‌جا به شهادت رسید. در ورودی مقبره، مجسمه رنگ‌برنزی را می‌بینید که نماد رشادت ایرانیان است. بنای شش‌ضلعی آرامگاه صدرالدین با آجرهای قرمز، سنگ‌های سفید و ملات گل‌ و خاک، سبک معماری صفوی را به نمایش می‌گذارد.\nآدرس: آذربایجان غربی، ۴ کیلومتری چالدران، بین روستای سعدل و گل اشاقی\nساعت کاری: ۱۰ صبح تا ۱۶\nهزینه ورودی: رایگان', 'در دل دشت‌های وسیع چالدران، آرامگاه سید صدرالدین صفوی قرار گرفته که این شخص، وزیر اعظم شاه اسماعیل اول صفوی بوده است. سید صدرالدین در جنگ چالدران با ۲۷ هزار سرباز در آن‌جا به شهادت رسید. در ورودی مقبره، مجسمه رنگ‌برنزی را می‌بینید که نماد رشادت ایرانیان است. بنای شش‌ضلعی آرامگاه صدرالدین با آجرهای قرمز، سنگ‌های سفید و ملات گل‌ و خاک، سبک معماری صفوی را به نمایش می‌گذارد.\nآدرس: آذربایجان غربی، ۴ کیلومتری چالدران، بین روستای سعدل و گل اشاقی\nساعت کاری: ۱۰ صبح تا ۱۶\nهزینه ورودی: رایگان', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:26:18'),
	(96, 'a135ce8a-14d0-43fd-9da9-378ed0352071', 26, 'قلعه بسطام', 'قلعه بسطام یا دژ بسطام بر بالای صخره‌ای (حدود ۶۴۵ سال پیش از میلاد) برای کنترل مسیرهای تجارتی شرق به غرب ساخته شد. پایین این قلعه برای سربازان و اسب‌ها و وسط قلعه به عنوان معبد کاربرد داشت و بالا‌ی قلعه مخصوص پادشاه بود. قلعه بسطام، روزگاری بزرگ‌ترین مرکز تمدن اورارتو (یکی از تمدن‌های مهم در عصر آهن) بود. سال‌ها بعد، پس از سقوط اورارتو، مسیحیان قلعه بسطام را در دست گرفتند و صلیب‌های حک‌شده بر سنگ‌هایش، روایت‌گر آن روزهاست.\nآدرس: استان آذربایجان غربی، ۹ کیلومتری غرب شهر قره‌ضیاالدین، مجاورت روستا', 'قلعه بسطام یا دژ بسطام بر بالای صخره‌ای (حدود ۶۴۵ سال پیش از میلاد) برای کنترل مسیرهای تجارتی شرق به غرب ساخته شد. پایین این قلعه برای سربازان و اسب‌ها و وسط قلعه به عنوان معبد کاربرد داشت و بالا‌ی قلعه مخصوص پادشاه بود. قلعه بسطام، روزگاری بزرگ‌ترین مرکز تمدن اورارتو (یکی از تمدن‌های مهم در عصر آهن) بود. سال‌ها بعد، پس از سقوط اورارتو، مسیحیان قلعه بسطام را در دست گرفتند و صلیب‌های حک‌شده بر سنگ‌هایش، روایت‌گر آن روزهاست.\nآدرس: استان آذربایجان غربی، ۹ کیلومتری غرب شهر قره‌ضیاالدین، مجاورت روستای بسطام', 36.6244548, 55.0510153, '2026-07-30 20:12:02', '2026-07-30 20:26:22'),
	(97, '9710d913-0036-47b7-815c-15052ad6ebad', 26, 'تالاب ناور', 'تالاب ناور یکی از جاهای آذربایجان غربی در غرب چالدران است که هر سال میزبان بیش از ۱۰ هزار پرنده مهاجر از گونه‌هایی مانند درنای خاکستری، غاز و اردک می‌شود. دشت‌های اطراف این تالاب با نیزارهای بلند و صدای پرندگان در حال پرواز، لحظه‌هایی زیبا را برای شما خلق می‌کنند.\nآدرس: آذربایجان غربی، غرب سیه چشمه (چالدران)', 'تالاب ناور یکی از جاهای آذربایجان غربی در غرب چالدران است که هر سال میزبان بیش از ۱۰ هزار پرنده مهاجر از گونه‌هایی مانند درنای خاکستری، غاز و اردک می‌شود. دشت‌های اطراف این تالاب با نیزارهای بلند و صدای پرندگان در حال پرواز، لحظه‌هایی زیبا را برای شما خلق می‌کنند.\nآدرس: آذربایجان غربی، غرب سیه چشمه (چالدران)', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:26:30'),
	(98, 'e2bcc671-34dd-4b9c-9cb3-6e37c4e9d25e', 26, 'آرامگاه ساندوخت', 'آرامگاه ساندوخت بنایی مکعبی و تاریخی است که روی بلندترین نقطه کلیسای تادئوس مقدس قرار دارد. این آرامگاه به ساندوخت، دختر پادشاه ارمنستان تعلق دارد که به خاطر ایمانش به شهادت رسید و اولین شهید مسیحیت لقب گرفت. مقبره این بانو یادآور روزی است که به‌خاطر باور خود، به دستور پدرش جان سپرد.\nآدرس: چالدران، نزدیک روستای کلیسا کندی، جنوب غربی بنای تاریخی قره کلیسا', 'آرامگاه ساندوخت بنایی مکعبی و تاریخی است که روی بلندترین نقطه کلیسای تادئوس مقدس قرار دارد. این آرامگاه به ساندوخت، دختر پادشاه ارمنستان تعلق دارد که به خاطر ایمانش به شهادت رسید و اولین شهید مسیحیت لقب گرفت. مقبره این بانو یادآور روزی است که به‌خاطر باور خود، به دستور پدرش جان سپرد.\nآدرس: چالدران، نزدیک روستای کلیسا کندی، جنوب غربی بنای تاریخی قره کلیسا', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:26:39'),
	(99, '06eaad10-87a9-40e6-9b06-b1f708b01953', 26, 'کاخ موزه باغچه جوق ماکو', 'کاخ‌موزه باغچه‌جوق در اواخر دوره قاجار با طاق‌های زیبا، ایوان‌های باشکوه و تزیینات آجری و کاشی‌کاری ساخته شد. ساختمان این کاخ دارای حیاط مرکزی، تالارهای مجلل و اتاق‌های پذیرایی است که امروزه به موزه‌ای از آثار تاریخی و فرهنگی تبدیل شده‌اند. از جمله دیدنی‌های کاخ موزه باغچه‌جوق، تالار آیینه با حوض‌خانه‌ زیبا، اتاق سبز با سقف نقاشی‌شده و اتاق شاه‌نشین با مبلمان لهستانی هستند. هم‌چنین، در این کاخ می توانید اولین گرامافون وارداتی به ایران و سلاح‌های سرد جنگ‌های جهانی را ببینید. گفتنی‌ست این کاخ در ز', 'کاخ‌موزه باغچه‌جوق در اواخر دوره قاجار با طاق‌های زیبا، ایوان‌های باشکوه و تزیینات آجری و کاشی‌کاری ساخته شد. ساختمان این کاخ دارای حیاط مرکزی، تالارهای مجلل و اتاق‌های پذیرایی است که امروزه به موزه‌ای از آثار تاریخی و فرهنگی تبدیل شده‌اند. از جمله دیدنی‌های کاخ موزه باغچه‌جوق، تالار آیینه با حوض‌خانه‌ زیبا، اتاق سبز با سقف نقاشی‌شده و اتاق شاه‌نشین با مبلمان لهستانی هستند. هم‌چنین، در این کاخ می توانید اولین گرامافون وارداتی به ایران و سلاح‌های سرد جنگ‌های جهانی را ببینید. گفتنی‌ست این کاخ در زمان گذشته محل حکومت سردار ماکو بوده است.\nآدرس: آذربایجان غربی، ۲ کیلومتری جاده ماکو-بازرگان، روستای باغچه جوق\nساعت بازدید: هر روز از ۹ صبح تا ۱۸\nقیمت بلیط: ۲۰ هزار تومان', 39.2894179, 44.4260578, '2026-07-30 20:12:02', '2026-07-30 20:26:42'),
	(100, '04ff94c7-1d33-4a00-900e-41f8907a5e7d', 26, 'منشور بازالتی ماکو', 'منشور بازالتی ماکو لقب یکی از عجیب‌ترین پدیده‌های زمین‌شناسی جهان را گرفته است. این کوه‌های شش‌ضلعی و هندسی که به نام «ایلان درسی» یا «دره مارها» در میان مردم محلی معروف هستند، از انجماد گدازه‌های آتشفشانی در دوره سوم زمین‌شناسی ساخته شده‌اند. سرد شدن تدریجی این گدازه‌ها باعث ایجاد شکاف‌های منظم و ستون‌های بازالتی در ابعاد مختلف شده است. در این منطقه، دره‌ای با دیواره‌های بلند و پوشش گیاهی متنوع قرار دارد که زیبایی طبیعی آن را دوچندان می‌کند. به علاوه چشمه‌ای به نام «خاتون بولاغی» یا «چشمه خاتون', 'منشور بازالتی ماکو لقب یکی از عجیب‌ترین پدیده‌های زمین‌شناسی جهان را گرفته است. این کوه‌های شش‌ضلعی و هندسی که به نام «ایلان درسی» یا «دره مارها» در میان مردم محلی معروف هستند، از انجماد گدازه‌های آتشفشانی در دوره سوم زمین‌شناسی ساخته شده‌اند. سرد شدن تدریجی این گدازه‌ها باعث ایجاد شکاف‌های منظم و ستون‌های بازالتی در ابعاد مختلف شده است. در این منطقه، دره‌ای با دیواره‌های بلند و پوشش گیاهی متنوع قرار دارد که زیبایی طبیعی آن را دوچندان می‌کند. به علاوه چشمه‌ای به نام «خاتون بولاغی» یا «چشمه خاتون» از میان دو ستون بازالتی جوشیده است.\nآدرس: ۲۵ کیلومتری ماکو، جاده ماکو–چالدران، بخش دشتک، جاده آواجیق', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:26:50'),
	(101, '28d3a83c-15c7-4b54-b10b-104323aa467e', 26, 'کلیسای زور زور (مریم مقدس) ماکو', 'در شمال‌ غربی ایران و نزدیک روستای بارون، کلیسای مریم مقدس زور زور در دل طبیعت ماکو می‌درخشد. از این بنا که روزگاری بخشی از صومعه‌ای بزرگ بوده، تنها همان کلیسا باقی مانده است. در اطراف کلیسای زور زور، طبیعت زیبایی از رودخانه زنگی‌مار و کوه‌های سر‌به‌فلک‌کشیده به چشم می‌خورد. یکی از عجیب‌ترین داستان‌های این کلیسا، جابه‌جایی کامل آن در هنگام ساخت سد بارون است. ماجرا از این قرار است که تمام سنگ‌های بنای این کلیسا، طی ۲۵ روز به فاصله‌ ۶۰۰ متر دورتر منتقل شدند و دوباره بدون هیچ‌گونه ملاتی کنار هم چید', 'در شمال‌ غربی ایران و نزدیک روستای بارون، کلیسای مریم مقدس زور زور در دل طبیعت ماکو می‌درخشد. از این بنا که روزگاری بخشی از صومعه‌ای بزرگ بوده، تنها همان کلیسا باقی مانده است. در اطراف کلیسای زور زور، طبیعت زیبایی از رودخانه زنگی‌مار و کوه‌های سر‌به‌فلک‌کشیده به چشم می‌خورد. یکی از عجیب‌ترین داستان‌های این کلیسا، جابه‌جایی کامل آن در هنگام ساخت سد بارون است. ماجرا از این قرار است که تمام سنگ‌های بنای این کلیسا، طی ۲۵ روز به فاصله‌ ۶۰۰ متر دورتر منتقل شدند و دوباره بدون هیچ‌گونه ملاتی کنار هم چیده شدند.\nآدرس: آذربایجان غربی، شهرستان ماکو، ۱۲ کیلومتری شمال غرب قره کلیسا، نزدیک روستای بارون', 35.6956557, 51.3767668, '2026-07-30 20:12:02', '2026-07-30 20:27:32'),
